    #[test]
    fn snapshot_round_trip_preserves_canonical_hash() {
        let (mut world, _, _) = world_with_two_actors();
        let creature_id = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_canonical_combat_stats"),
                position: WorldPosition { x: 2, y: 1, z: 0 },
                hp: 10,
                speed: 100,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 4,
                dodge: 2,
                size: Default::default(),
                melee_dice: 1,
                melee_dice_sides: 1,
                can_see: false,
                vision_day: 0,
                vision_night: 0,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("combat-stat creature should spawn");
        let before = world.canonical_hash().expect("state should hash");
        let restored =
            WorldState::from_snapshot(&world.snapshot()).expect("snapshot should restore");
        let after = restored
            .canonical_hash()
            .expect("restored state should hash");
        assert_eq!(before, after);
        let mut changed_snapshot = world.snapshot();
        let changed = changed_snapshot
            .creatures
            .iter_mut()
            .find(|creature| creature.id == creature_id)
            .expect("combat-stat creature is canonical");
        changed.melee_skill = 5;
        changed.dodge = 3;
        let changed = WorldState::from_snapshot(&changed_snapshot)
            .expect("bounded changed combat stats should restore");
        assert_ne!(
            before,
            changed.canonical_hash().expect("changed state should hash"),
            "monster melee_skill and dodge must participate in CanonicalStateV55"
        );
    }

    #[test]
    fn item_snapshot_and_component_metadata_fail_closed() {
        let (mut world, actor_id, _) = world_with_two_actors();
        let position = world
            .actor_snapshot(actor_id)
            .expect("actor exists")
            .position;
        let item_id = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("metadata_fixture"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: None,
            })
            .expect("metadata fixture should spawn");
        let base = world
            .ground_item_snapshot(item_id)
            .expect("metadata fixture should remain")
            .item;

        let mut valid = base.clone();
        valid.snippet = Some(cdda_protocol::ItemSnippetV1 {
            id: String::from("note_fixture"),
            text: String::from("first line\nsecond line"),
        });
        valid.variables.insert(
            String::from("owner"),
            cdda_protocol::ItemVariableValueV1::String(String::from("survivor")),
        );
        assert!(validate_item_snapshot(&valid).is_ok());
        assert!(
            !same_item_stack_state(&base, &valid),
            "stacking must not discard canonical snippet or variable state"
        );
        let mut distinct_containment = base.clone();
        distinct_containment.containment.weight_milligrams = 1;
        assert!(
            !same_item_stack_state(&base, &distinct_containment),
            "self-contained physical state also participates in stack identity"
        );
        let mut unfitted = base.clone();
        unfitted.containment.flags = vec![String::from("VARSIZE")];
        let mut fitted = unfitted.clone();
        fitted.fitted = true;
        assert!(validate_item_snapshot(&fitted).is_ok());
        assert!(
            !same_item_stack_state(&unfitted, &fitted),
            "fitted and unfitted instances must not merge into one stack"
        );
        let mut immutable_fit = base.clone();
        immutable_fit.containment.flags = vec![String::from("FIT")];
        assert!(matches!(
            validate_item_snapshot(&immutable_fit),
            Err(SimError::InvalidItem)
        ));
        immutable_fit.fitted = true;
        assert!(validate_item_snapshot(&immutable_fit).is_ok());

        let mut empty_snippet = valid.clone();
        empty_snippet
            .snippet
            .as_mut()
            .expect("snippet exists")
            .text
            .clear();
        assert!(matches!(
            validate_item_snapshot(&empty_snippet),
            Err(SimError::InvalidItem)
        ));
        let mut invalid_variable = valid.clone();
        invalid_variable.variables.insert(
            String::from("bad\0key"),
            cdda_protocol::ItemVariableValueV1::Integer(1),
        );
        assert!(matches!(
            validate_item_snapshot(&invalid_variable),
            Err(SimError::InvalidItem)
        ));
        let mut duplicate_flags = valid.clone();
        duplicate_flags.containment.flags = vec![String::from("RIGID"), String::from("RIGID")];
        assert!(matches!(
            validate_item_snapshot(&duplicate_flags),
            Err(SimError::InvalidItem)
        ));
        let mut empty_charge_stack = valid.clone();
        empty_charge_stack.charges = 0;
        empty_charge_stack.containment.count_by_charges = true;
        assert!(matches!(
            validate_item_snapshot(&empty_charge_stack),
            Err(SimError::InvalidItem)
        ));

        let consumed = CraftConsumedItemV1 {
            item: valid,
            split_from: None,
        };
        let component = component_from_consumed(&consumed, false, true);
        assert!(validate_item_component_root(&component).is_ok());

        let mut component_empty_snippet = component.clone();
        component_empty_snippet
            .snippet
            .as_mut()
            .expect("snippet exists")
            .text
            .clear();
        assert!(matches!(
            validate_item_component_root(&component_empty_snippet),
            Err(SimError::InvalidItem)
        ));
        let mut component_invalid_variable = component.clone();
        component_invalid_variable.variables.insert(
            String::new(),
            cdda_protocol::ItemVariableValueV1::Integer(1),
        );
        assert!(matches!(
            validate_item_component_root(&component_invalid_variable),
            Err(SimError::InvalidItem)
        ));
        let mut component_duplicate_flags = component.clone();
        component_duplicate_flags.containment.flags =
            vec![String::from("RIGID"), String::from("RIGID")];
        assert!(matches!(
            validate_item_component_root(&component_duplicate_flags),
            Err(SimError::InvalidItem)
        ));
        let mut component_immutable_fit = component.clone();
        component_immutable_fit.containment.flags = vec![String::from("FIT")];
        assert!(matches!(
            validate_item_component_root(&component_immutable_fit),
            Err(SimError::InvalidItem)
        ));
        component_immutable_fit.fitted = true;
        assert!(validate_item_component_root(&component_immutable_fit).is_ok());
        let mut component_charge_mode_mismatch = component.clone();
        component_charge_mode_mismatch.containment.count_by_charges = true;
        assert!(matches!(
            validate_item_component_root(&component_charge_mode_mismatch),
            Err(SimError::InvalidItem)
        ));

        let mut prototype = test_craft_item_prototype("metadata_fixture");
        prototype.containment = component.containment.clone();
        validate_craft_item_prototype(&prototype).expect("prototype should be valid");
        let reconstructed = item_from_craft_prototype(ItemId::new(1, 99), &prototype, SimTick(0));
        validate_item_snapshot(&reconstructed.snapshot())
            .expect("an admitted prototype must reconstruct a valid item");
        let mut empty_charge_prototype = prototype.clone();
        empty_charge_prototype.charges = 0;
        empty_charge_prototype.containment.count_by_charges = true;
        assert!(matches!(
            validate_craft_item_prototype(&empty_charge_prototype),
            Err(SimError::InvalidCraft)
        ));
        assert!(component_state_matches_prototype(&component, &prototype));
        prototype.containment.weight_milligrams = 1;
        assert!(!component_state_matches_prototype(&component, &prototype));
    }

    #[test]
    fn furniture_blocks_authoritative_movement_and_survives_snapshot_round_trip() {
        let mut world = WorldState::new(39, [31; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let dresser = test_furniture("f_dresser", -1, true);
        chunk
            .set_furniture(LocalTileCoord { x: 2, y: 1 }, Some(dresser.clone()))
            .expect("dresser should install");
        world.insert_chunk(chunk);
        let actor_id = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should spawn");
        make_actor_act_each_tick(&mut world, actor_id);

        let outcome = world
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(1),
                client_tick: world.tick(),
                kind: CommandKind::Move {
                    dx: 1,
                    dy: 0,
                    dz: 0,
                },
            }])
            .expect("blocked move should resolve deterministically");
        assert!(matches!(
            outcome.events[0].kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::Blocked,
                ..
            }
        ));
        assert_eq!(
            world
                .actor_snapshot(actor_id)
                .expect("actor exists")
                .position,
            WorldPosition { x: 1, y: 1, z: 0 }
        );

        let snapshot = world.snapshot();
        let index = usize::from(1_u8) * SUBMAP_SIZE as usize + usize::from(2_u8);
        assert_eq!(snapshot.chunks[0].furniture[index], Some(dresser));
        let restored = WorldState::from_snapshot(&snapshot).expect("furniture should restore");
        assert_eq!(
            restored.canonical_hash().expect("restored hash"),
            world.canonical_hash().expect("original hash")
        );
    }

    #[test]
    fn furniture_and_terrain_costs_create_deterministic_movement_debt() {
        let mut world = WorldState::new(41, [33; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        chunk
            .set_furniture(
                LocalTileCoord { x: 2, y: 1 },
                Some(FurnitureTileSnapshot {
                    furniture_id: String::from("f_bed"),
                    move_cost_mod: 3,
                    transparent: true,
                    blocks_door: false,
                    comfort: 5,
                    floor_bedding_warmth: 1_000,
                }),
            )
            .expect("bed should install");
        world.insert_chunk(chunk);
        let actor_id = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should spawn with one banked ordinary action");

        world
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(1),
                client_tick: world.tick(),
                kind: CommandKind::Move {
                    dx: 1,
                    dy: 0,
                    dz: 0,
                },
            }])
            .expect("floor-to-bed move should execute immediately");
        let actor = world.actor_snapshot(actor_id).expect("actor exists");
        assert_eq!(actor.position, WorldPosition { x: 2, y: 1, z: 0 });
        assert_eq!(
            actor.action_points, -1_500,
            "average tile cost (2 + 5) * 500 charges 3,500 readiness"
        );

        world
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(2),
                client_tick: world.tick(),
                kind: CommandKind::Move {
                    dx: 1,
                    dy: 0,
                    dz: 0,
                },
            }])
            .expect("exit move should queue while debt recovers");
        assert_eq!(
            world
                .actor_snapshot(actor_id)
                .expect("actor exists")
                .position,
            WorldPosition { x: 2, y: 1, z: 0 }
        );
        for _ in 0..33 {
            world
                .advance_tick(Vec::new())
                .expect("movement debt should recover deterministically");
        }
        assert_eq!(
            world
                .actor_snapshot(actor_id)
                .expect("actor exists")
                .action_points,
            1_900
        );
        world
            .advance_tick(Vec::new())
            .expect("exit move should execute at the exact readiness boundary");
        let actor = world.actor_snapshot(actor_id).expect("actor exists");
        assert_eq!(actor.position, WorldPosition { x: 3, y: 1, z: 0 });
        assert_eq!(actor.action_points, -1_500);

        let restored = WorldState::from_snapshot(&world.snapshot())
            .expect("negative movement debt should restore");
        assert_eq!(
            restored.canonical_hash().expect("restored hash"),
            world.canonical_hash().expect("original hash")
        );
    }

