    #[test]
    fn fatal_ranged_attack_rejects_atomically_when_corpse_id_is_unavailable() {
        let mut world = WorldState::new(50, [50; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 3).expect("valid short block"))
            .expect("short block should install");
        world.insert_chunk(Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 }));
        let actor = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should use first ID");
        let weapon_id = world
            .spawn_ground_item(ItemSpawn {
                position: WorldPosition { x: 1, y: 1, z: 0 },
                type_id: String::from("test_revolver"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: Some(RangedWeaponSnapshot {
                    ammunition_type: String::from("38"),
                    ammunition_remaining: 1,
                    ammunition_capacity: 1,
                    range: 5,
                    damage: 10,
                    dispersion: 0,
                    sound_volume: 0,
                }),
            })
            .expect("weapon should use second ID");
        let weapon = world
            .ground_items
            .remove(&weapon_id)
            .expect("weapon should exist")
            .item;
        let actor_state = world.actors.get_mut(&actor).expect("actor should exist");
        actor_state.inventory.insert(weapon_id, weapon);
        actor_state.wielded = Some(weapon_id);
        actor_state.action_points = i64::from(ACTOR_ACTION_THRESHOLD);
        let prototype = CreatureCorpsePrototypeV1 {
            monster_type_id: String::from("mon_test"),
            max_hp: 10,
            speed: 100,
            attack_cost_moves: 100,
            aggression: 0,
            melee_skill: 0,
            dodge: 0,
            size: Default::default(),
            melee_dice: 1,
            melee_dice_sides: 1,
            can_see: true,
            vision_day: 60,
            vision_night: 60,
            stumbles: false,
            bashes: false,
            group_bash: false,
            hears: false,
            good_hearing: false,
            clumsy_attacks: false,
            immobile: false,
            pacifist: false,
            can_open_doors: false,
            path_settings: Default::default(),
            blood_field_type_id: String::new(),
            revives: false,
        };
        let target = world
            .spawn_creature(CreatureSpawn {
                type_id: prototype.monster_type_id.clone(),
                position: WorldPosition { x: 3, y: 1, z: 0 },
                hp: 10,
                speed: 100,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 1,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: Some(prototype),
            })
            .expect("creature should use final ID");
        let outcome = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(1),
                client_tick: SimTick(0),
                kind: CommandKind::ShootCreature { target },
            }])
            .expect("ID shortage should be a typed rejection, not a failed tick");
        assert!(outcome.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                actor_id,
                sequence: CommandSequence(1),
                reason: CommandRejection::StableIdsUnavailable,
            } if actor_id == actor
        )));
        assert_eq!(
            world.creature_snapshot(target).expect("target remains").hp,
            10
        );
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory
                .iter()
                .find(|item| item.id == weapon_id)
                .and_then(|item| item.ranged_weapon.as_ref())
                .map(|weapon| weapon.ammunition_remaining),
            Some(1)
        );
        assert!(world.snapshot().ground_items.is_empty());
    }

    #[test]
    fn ranged_weapon_spends_ammunition_and_kills_deterministically() {
        let mut world = WorldState::new(15, [10; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        world.insert_chunk(Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 }));
        let actor = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should spawn");
        make_actor_act_each_tick(&mut world, actor);
        let weapon = world
            .spawn_ground_item(ItemSpawn {
                position: WorldPosition { x: 1, y: 1, z: 0 },
                type_id: String::from("test_revolver"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: Some(RangedWeaponSnapshot {
                    ammunition_type: String::from("38"),
                    ammunition_remaining: 2,
                    ammunition_capacity: 6,
                    range: 10,
                    damage: 10,
                    dispersion: 0,
                    sound_volume: 0,
                }),
            })
            .expect("weapon should spawn");
        let creature = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_target"),
                position: WorldPosition { x: 5, y: 1, z: 0 },
                hp: 10,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("target should spawn");
        let commands = [
            CommandKind::PickUp { item_id: weapon },
            CommandKind::Wield { item_id: weapon },
            CommandKind::ShootCreature { target: creature },
        ];
        let mut shot_events = Vec::new();
        for (index, kind) in commands.into_iter().enumerate() {
            shot_events = world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence((index + 1) as u64),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("ranged action should advance")
                .events;
        }
        assert!(matches!(
            shot_events[0].kind,
            WorldEventKind::RangedAttackResolved {
                source,
                weapon: event_weapon,
                target: RangedTarget::Creature(event_target),
                hit: true,
                remaining_ammunition: 1,
                ..
            } if source == actor && event_weapon == weapon && event_target == creature
        ));
        assert!(matches!(
            shot_events[2].kind,
            WorldEventKind::CreatureDied { creature_id, killer }
                if creature_id == creature && killer == actor
        ));
        let actor = world.actor_snapshot(actor).expect("actor remains");
        assert_eq!(
            actor.inventory[0]
                .ranged_weapon
                .as_ref()
                .expect("weapon stats persist")
                .ammunition_remaining,
            1
        );
        world.tick = SimTick(13 * 60 * 60 * SimTick::HZ);
        let dark_target = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_dark_target"),
                position: WorldPosition { x: 5, y: 1, z: 0 },
                hp: 10,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("dark target should spawn on the dead creature's tile");
        let dark_shot = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor.id,
                sequence: CommandSequence(4),
                client_tick: world.tick(),
                kind: CommandKind::ShootCreature {
                    target: dark_target,
                },
            }])
            .expect("dark shot should resolve");
        assert!(dark_shot.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::NoClearShot,
                ..
            }
        )));
        assert_eq!(
            world
                .actor_snapshot(actor.id)
                .expect("actor remains")
                .inventory[0]
                .ranged_weapon
                .as_ref()
                .expect("weapon remains")
                .ammunition_remaining,
            1,
            "an unseen targeted shot must not spend ammunition"
        );
        WorldState::from_snapshot(&world.snapshot()).expect("ranged state should round trip");
    }

    #[test]
    fn gunfire_drives_private_deterministic_hearing_goals_with_visual_memory_priority() {
        let mut world = WorldState::new(56, [56; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let wall = TerrainTileSnapshot {
            terrain_id: String::from("t_wall"),
            move_cost: 0,
            transparent: false,
            flat: false,
            open: String::new(),
            open_move_cost: None,
            open_transparent: None,
            open_flat: None,
            close: String::new(),
            close_move_cost: None,
            close_transparent: None,
            close_flat: None,
        };
        for y in 0..cdda_protocol::SUBMAP_SIZE as u8 {
            chunk
                .set_terrain(LocalTileCoord { x: 5, y }, wall.clone())
                .expect("occluding wall should install");
        }
        world.insert_chunk(chunk);
        let actor = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should spawn");
        make_actor_act_each_tick(&mut world, actor);
        let weapon = world
            .spawn_ground_item(ItemSpawn {
                position: WorldPosition { x: 1, y: 1, z: 0 },
                type_id: String::from("test_revolver"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: Some(RangedWeaponSnapshot {
                    ammunition_type: String::from("38"),
                    ammunition_remaining: 2,
                    ammunition_capacity: 6,
                    range: 10,
                    damage: 1,
                    dispersion: 0,
                    sound_volume: 70,
                }),
            })
            .expect("weapon should spawn");
        let target = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_target"),
                position: WorldPosition { x: 2, y: 1, z: 0 },
                hp: 10,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("target should spawn");
        let listener_speed =
            u16::try_from(CREATURE_ACTION_THRESHOLD).expect("action threshold fits u16");
        let spawn_listener = |world: &mut WorldState,
                              type_id: &str,
                              position: WorldPosition,
                              hears: bool,
                              good_hearing: bool| {
            world
                .spawn_creature(CreatureSpawn {
                    type_id: type_id.to_owned(),
                    position,
                    hp: 20,
                    speed: listener_speed,
                    attack_cost_moves: 100,
                    aggression: 100,
                    melee_skill: 0,
                    dodge: 0,
                    size: Default::default(),
                    melee_dice: 1,
                    melee_dice_sides: 1,
                    can_see: true,
                    vision_day: 60,
                    vision_night: 60,
                    stumbles: false,
                    bashes: false,
                    group_bash: false,
                    hears,
                    good_hearing,
                    clumsy_attacks: false,
                    immobile: false,
                    pacifist: false,
                    can_open_doors: false,
                    path_settings: Default::default(),
                    blood_field_type_id: String::new(),
                    corpse: None,
                })
                .expect("listener should spawn")
        };
        let listener = spawn_listener(
            &mut world,
            "mon_listener",
            WorldPosition { x: 8, y: 2, z: 0 },
            true,
            false,
        );
        let deaf = spawn_listener(
            &mut world,
            "mon_deaf",
            WorldPosition { x: 8, y: 4, z: 0 },
            false,
            false,
        );
        let good_listener = spawn_listener(
            &mut world,
            "mon_good_listener",
            WorldPosition { x: 8, y: 6, z: 0 },
            true,
            true,
        );
        let remembered = spawn_listener(
            &mut world,
            "mon_remembered_target",
            WorldPosition { x: 8, y: 8, z: 0 },
            true,
            false,
        );
        let remembered_destination = WorldPosition { x: 8, y: 10, z: 0 };
        assert!(matches!(
            world.spawn_creature(CreatureSpawn {
                type_id: String::from("mon_invalid_hearing"),
                position: WorldPosition { x: 10, y: 10, z: 0 },
                hp: 1,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: false,
                vision_day: 0,
                vision_night: 0,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: true,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            }),
            Err(SimError::InvalidCreature)
        ));

        let commands = [
            CommandKind::PickUp { item_id: weapon },
            CommandKind::Wield { item_id: weapon },
            CommandKind::ShootCreature { target },
        ];
        let mut shot = None;
        for (index, kind) in commands.into_iter().enumerate() {
            if index == 2 {
                world
                    .creatures
                    .get_mut(&remembered)
                    .expect("listener should exist")
                    .goal = Some(remembered_destination);
            }
            shot = Some(
                world
                    .advance_tick(vec![ClientCommand {
                        actor_id: actor,
                        sequence: CommandSequence((index + 1) as u64),
                        client_tick: world.tick(),
                        kind,
                    }])
                    .expect("ranged action should advance"),
            );
        }
        let shot = shot.expect("shot outcome should exist");
        assert!(shot.events.iter().any(|event| matches!(
            &event.kind,
            WorldEventKind::RangedAttackResolved {
                origin: WorldPosition { x: 1, y: 1, z: 0 },
                sound,
                sound_volume: 70,
                ..
            } if sound == "bang!"
        )));

        let listener = world
            .creature_snapshot(listener)
            .expect("listener should remain");
        assert!(
            listener.position.x < 8,
            "the hidden listener pursues the shot"
        );
        assert_eq!(
            listener.sound_goal,
            Some(CreatureSoundGoalV1 {
                position: WorldPosition { x: 1, y: 1, z: 0 },
                remaining_actions: 62,
            })
        );
        let deaf = world
            .creature_snapshot(deaf)
            .expect("deaf creature remains");
        assert_eq!(deaf.position, WorldPosition { x: 8, y: 4, z: 0 });
        assert_eq!(deaf.sound_goal, None);
        let good_listener = world
            .creature_snapshot(good_listener)
            .expect("good listener should remain");
        assert!(good_listener.position.x < 8);
        assert_eq!(
            good_listener
                .sound_goal
                .expect("good hearing should retain a longer goal")
                .remaining_actions,
            797
        );
        let remembered = world
            .creature_snapshot(remembered)
            .expect("remembering listener should remain");
        assert_eq!(remembered.position, WorldPosition { x: 8, y: 9, z: 0 });
        assert_eq!(remembered.goal, Some(remembered_destination));
        assert_eq!(
            remembered
                .sound_goal
                .expect("the lower-priority sound remains canonical")
                .position,
            WorldPosition { x: 1, y: 1, z: 0 }
        );

        let mut invalid_lifetime = world.snapshot();
        invalid_lifetime
            .creatures
            .iter_mut()
            .find(|creature| creature.id == listener.id)
            .and_then(|creature| creature.sound_goal.as_mut())
            .expect("listener should expose private snapshot state")
            .remaining_actions = MAX_CREATURE_SOUND_GOAL_ACTIONS + 1;
        assert!(matches!(
            WorldState::from_snapshot(&invalid_lifetime),
            Err(SimError::InvalidCreature)
        ));

        let mut restored = WorldState::from_snapshot(&world.snapshot())
            .expect("private hearing state should restore");
        assert_eq!(
            restored.canonical_hash().expect("restored state hashes"),
            world.canonical_hash().expect("live state hashes")
        );
        restored
            .creatures
            .get_mut(&listener.id)
            .and_then(|creature| creature.sound_goal.as_mut())
            .expect("listener should retain its sound goal")
            .remaining_actions = 1;
        restored
            .advance_tick(Vec::new())
            .expect("sound-goal expiry should advance");
        assert_eq!(
            restored
                .creature_snapshot(listener.id)
                .expect("listener should remain")
                .sound_goal,
            None,
            "sound pursuit expires once per creature action"
        );

        let edge_source = WorldPosition {
            x: i32::MAX,
            y: i32::MAX,
            z: 0,
        };
        restored.insert_chunk(Chunk::floor(edge_source.chunk_and_local().0));
        let edge_listener = restored
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_edge_listener"),
                position: WorldPosition {
                    x: i32::MAX - 1,
                    y: i32::MAX - 1,
                    z: 0,
                },
                hp: 1,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: false,
                vision_day: 0,
                vision_night: 0,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: true,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("edge listener should spawn");
        for event_id in 0..128 {
            restored
                .creatures
                .get_mut(&edge_listener)
                .expect("edge listener should remain")
                .sound_goal = None;
            restored
                .creature_hear_sound(edge_listener, edge_source, 2, true, event_id)
                .expect("imprecise edge sound must saturate instead of aborting a tick");
        }
    }

    #[test]
    fn capable_creature_opens_and_enters_terrain_door_at_pinned_zero_move_cost() {
        let mut base = WorldState::new(57, [57; 32]);
        base.install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let mut wall = test_terrain("t_wall");
        wall.move_cost = 0;
        wall.transparent = false;
        for x in 0..SUBMAP_SIZE as u8 {
            for y in [0, 2] {
                chunk
                    .set_terrain(LocalTileCoord { x, y }, wall.clone())
                    .expect("corridor wall should install");
            }
        }
        let closed_door = TerrainTileSnapshot {
            terrain_id: String::from("t_door_c"),
            move_cost: 0,
            transparent: true,
            flat: false,
            open: String::from("t_door_o"),
            open_move_cost: Some(2),
            open_transparent: Some(true),
            open_flat: Some(true),
            close: String::new(),
            close_move_cost: None,
            close_transparent: None,
            close_flat: None,
        };
        chunk
            .set_terrain(LocalTileCoord { x: 4, y: 1 }, closed_door.clone())
            .expect("door should install");
        chunk
            .set_map_damage(LocalTileCoord { x: 4, y: 1 }, 2)
            .expect("partial structural damage should install");
        base.insert_chunk(chunk);
        base.spawn_actor(WorldPosition { x: 5, y: 1, z: 0 }, true)
            .expect("target actor should spawn");
        let spawn = |world: &mut WorldState, can_see, can_open_doors| {
            world
                .spawn_creature(CreatureSpawn {
                    type_id: String::from("mon_door_test"),
                    position: WorldPosition { x: 3, y: 1, z: 0 },
                    hp: 20,
                    speed: u16::try_from(CREATURE_ACTION_THRESHOLD).expect("threshold fits u16"),
                    attack_cost_moves: 100,
                    aggression: 100,
                    melee_skill: 0,
                    dodge: 0,
                    size: Default::default(),
                    melee_dice: 1,
                    melee_dice_sides: 1,
                    can_see,
                    vision_day: if can_see { 60 } else { 0 },
                    vision_night: if can_see { 60 } else { 0 },
                    stumbles: false,
                    bashes: false,
                    group_bash: false,
                    hears: true,
                    good_hearing: false,
                    clumsy_attacks: false,
                    immobile: false,
                    pacifist: false,
                    can_open_doors,
                    path_settings: CreaturePathSettingsV1 {
                        max_distance: 45,
                        allow_open_doors: can_open_doors,
                        ..CreaturePathSettingsV1::default()
                    },
                    blood_field_type_id: String::new(),
                    corpse: None,
                })
                .expect("door-test creature should spawn")
        };

        let mut incapable = base.clone();
        let incapable_id = spawn(&mut incapable, true, false);
        let incapable_outcome = incapable
            .advance_tick(Vec::new())
            .expect("incapable turn should advance");
        assert!(incapable_outcome.events.is_empty());
        assert_eq!(
            incapable
                .creature_snapshot(incapable_id)
                .expect("incapable creature should remain")
                .position,
            WorldPosition { x: 3, y: 1, z: 0 }
        );
        assert_eq!(
            incapable.snapshot().chunks[0].tiles
                [tile_index(LocalTileCoord { x: 4, y: 1 }).expect("door index")]
            .terrain_id,
            "t_door_c"
        );

        let mut visible = base.clone();
        let visible_id = spawn(&mut visible, true, true);
        let visible_outcome = visible
            .advance_tick(Vec::new())
            .expect("visible door-opening turn should advance");
        assert!(matches!(
            &visible_outcome.events[0].kind,
            WorldEventKind::CreatureOpenedTerrain {
                creature_id,
                position: WorldPosition { x: 4, y: 1, z: 0 },
                from,
                to,
                sound,
                volume: 6,
            } if *creature_id == visible_id
                && from == "t_door_c"
                && to == "t_door_o"
                && sound == "swish"
        ));
        assert!(matches!(
            visible_outcome.events[1].kind,
            WorldEventKind::CreatureMoved {
                creature_id,
                from: WorldPosition { x: 3, y: 1, z: 0 },
                to: WorldPosition { x: 4, y: 1, z: 0 },
            } if creature_id == visible_id
        ));
        let visible_creature = visible
            .creature_snapshot(visible_id)
            .expect("visible opener should remain");
        assert_eq!(visible_creature.action_points, 0);
        assert!(visible_creature.can_open_doors);
        let door_index = tile_index(LocalTileCoord { x: 4, y: 1 }).expect("door index");
        assert_eq!(
            visible.snapshot().chunks[0].tiles[door_index].terrain_id,
            "t_door_o"
        );
        assert_eq!(visible.snapshot().chunks[0].map_damage[door_index], 0);
        WorldState::from_snapshot(&visible.snapshot())
            .expect("door-opening capability and terrain should restore");

        let mut sound_driven = base;
        let sound_driven_id = spawn(&mut sound_driven, false, true);
        sound_driven
            .creatures
            .get_mut(&sound_driven_id)
            .expect("sound-driven opener should exist")
            .sound_goal = Some(CreatureSoundGoalV1 {
            position: WorldPosition { x: 5, y: 1, z: 0 },
            remaining_actions: 10,
        });
        let sound_outcome = sound_driven
            .advance_tick(Vec::new())
            .expect("sound-driven door-opening turn should advance");
        assert!(matches!(
            sound_outcome.events[0].kind,
            WorldEventKind::CreatureOpenedTerrain { creature_id, .. }
                if creature_id == sound_driven_id
        ));
        assert_eq!(
            sound_driven
                .creature_snapshot(sound_driven_id)
                .expect("sound-driven opener should remain")
                .position,
            WorldPosition { x: 4, y: 1, z: 0 }
        );
    }

    #[test]
    fn content_routing_takes_a_deterministic_nonprogress_step_around_a_wall() {
        let mut base = WorldState::new(58, [58; 32]);
        base.install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let mut wall = test_terrain("t_wall");
        wall.move_cost = 0;
        wall.transparent = false;
        for y in 0..=2 {
            chunk
                .set_terrain(LocalTileCoord { x: 4, y }, wall.clone())
                .expect("barrier should install");
        }
        base.insert_chunk(chunk);
        let target_position = WorldPosition { x: 5, y: 1, z: 0 };
        base.spawn_actor(target_position, true)
            .expect("target actor should spawn");
        let spawn = |world: &mut WorldState, max_distance| {
            let id = world
                .spawn_creature(CreatureSpawn {
                    type_id: String::from("mon_route_test"),
                    position: WorldPosition { x: 3, y: 1, z: 0 },
                    hp: 20,
                    speed: u16::try_from(CREATURE_ACTION_THRESHOLD).expect("threshold fits"),
                    attack_cost_moves: 100,
                    aggression: 100,
                    melee_skill: 0,
                    dodge: 0,
                    size: Default::default(),
                    melee_dice: 1,
                    melee_dice_sides: 1,
                    can_see: false,
                    vision_day: 0,
                    vision_night: 0,
                    stumbles: false,
                    bashes: false,
                    group_bash: false,
                    hears: false,
                    good_hearing: false,
                    clumsy_attacks: false,
                    immobile: false,
                    pacifist: false,
                    can_open_doors: false,
                    path_settings: CreaturePathSettingsV1 {
                        max_distance,
                        ..CreaturePathSettingsV1::default()
                    },
                    blood_field_type_id: String::new(),
                    corpse: None,
                })
                .expect("route-test creature should spawn");
            world
                .creatures
                .get_mut(&id)
                .expect("route-test creature should remain")
                .goal = Some(target_position);
            id
        };

        let mut greedy = base.clone();
        let greedy_id = spawn(&mut greedy, 0);
        let greedy_outcome = greedy
            .advance_tick(Vec::new())
            .expect("greedy fallback tick should advance");
        assert!(greedy_outcome.events.is_empty());
        assert_eq!(
            greedy
                .creature_snapshot(greedy_id)
                .expect("greedy creature should remain")
                .position,
            WorldPosition { x: 3, y: 1, z: 0 }
        );

        let mut routed = base;
        let routed_id = spawn(&mut routed, 10);
        let planned_step = routed
            .creature_route_step(
                routed_id,
                WorldPosition { x: 3, y: 1, z: 0 },
                target_position,
            )
            .expect("route search should be valid");
        assert_eq!(planned_step, Some(WorldPosition { x: 3, y: 2, z: 0 }));
        let routed_outcome = routed
            .advance_tick(Vec::new())
            .expect("routed tick should advance");
        assert!(
            matches!(
                routed_outcome.events.as_slice(),
                [WorldEvent {
                    kind: WorldEventKind::CreatureMoved {
                        creature_id,
                        from: WorldPosition { x: 3, y: 1, z: 0 },
                        to: WorldPosition { x: 3, y: 2, z: 0 },
                    },
                    ..
                }] if *creature_id == routed_id
            ),
            "unexpected routed events: {:?}",
            (
                &routed_outcome.events,
                routed
                    .creature_snapshot(routed_id)
                    .expect("routed creature should remain")
            )
        );
        let routed_snapshot = routed
            .creature_snapshot(routed_id)
            .expect("routed creature should remain");
        assert_eq!(routed_snapshot.path_settings.max_distance, 10);
        assert_eq!(routed_snapshot.goal, Some(target_position));
        WorldState::from_snapshot(&routed.snapshot()).expect("routed state should round trip");

        let mut hostile = routed.snapshot();
        hostile.creatures[0].path_settings.max_distance = 401;
        assert!(matches!(
            WorldState::from_snapshot(&hostile),
            Err(SimError::InvalidCreature)
        ));
    }

    #[test]
    fn route_planned_bashing_uses_base_strength_and_pinned_costs() {
        let mut base = WorldState::new(61, [61; 32]);
        base.install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        base.register_terrain_bash_type(TerrainBashTypeV1 {
            terrain_id: String::from("t_door_c"),
            str_min: 6,
            str_max: 26,
            str_min_blocked: 150,
            str_max_blocked: 160,
            str_min_supported: -1,
            str_max_supported: -1,
            bash_multiplier_millionths: 1_000_000,
            result: test_terrain("t_floor"),
            drop_source: None,
            hit_field: None,
            destroyed_field: None,
            sound: String::from("smash!"),
            failure_sound: String::from("whump!"),
            sound_volume: 20,
            failure_sound_volume: 12,
        })
        .expect("door bash should register");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let mut wall = test_terrain("t_wall");
        wall.move_cost = 0;
        wall.transparent = false;
        for y in 0..=10 {
            chunk
                .set_terrain(LocalTileCoord { x: 4, y }, wall.clone())
                .expect("barrier should install");
        }
        let mut door = test_terrain("t_door_c");
        door.move_cost = 0;
        door.transparent = false;
        chunk
            .set_terrain(LocalTileCoord { x: 4, y: 5 }, door)
            .expect("door should install");
        base.insert_chunk(chunk);
        let from = WorldPosition { x: 3, y: 5, z: 0 };
        let target = WorldPosition { x: 5, y: 5, z: 0 };
        let spawn = |world: &mut WorldState, melee_dice, melee_dice_sides, group_bash| {
            let creature_id = world
                .spawn_creature(CreatureSpawn {
                    type_id: String::from("mon_route_basher"),
                    position: from,
                    hp: 20,
                    speed: u16::try_from(CREATURE_ACTION_THRESHOLD).expect("threshold fits"),
                    attack_cost_moves: 100,
                    aggression: 100,
                    melee_skill: 0,
                    dodge: 0,
                    size: Default::default(),
                    melee_dice,
                    melee_dice_sides,
                    can_see: false,
                    vision_day: 0,
                    vision_night: 0,
                    stumbles: false,
                    bashes: true,
                    group_bash,
                    hears: false,
                    good_hearing: false,
                    clumsy_attacks: false,
                    immobile: false,
                    pacifist: false,
                    can_open_doors: false,
                    path_settings: CreaturePathSettingsV1 {
                        max_distance: 20,
                        ..CreaturePathSettingsV1::default()
                    },
                    blood_field_type_id: String::new(),
                    corpse: None,
                })
                .expect("route basher should spawn");
            world
                .creatures
                .get_mut(&creature_id)
                .expect("route basher should remain")
                .goal = Some(target);
            creature_id
        };

        let mut strong = base.clone();
        let strong_id = spawn(&mut strong, 10, 10, false);
        let door_position = WorldPosition { x: 4, y: 5, z: 0 };
        assert_eq!(
            strong
                .creature_route_bash_rating(strong_id, door_position)
                .expect("route rating should compute"),
            Some(10)
        );
        assert_eq!(
            strong
                .creature_route_tile_cost(
                    strong_id,
                    strong.creatures.get(&strong_id).expect("strong basher"),
                    door_position,
                )
                .expect("route cost should compute"),
            Some(14)
        );
        assert_eq!(
            strong
                .creature_route_step(strong_id, from, target)
                .expect("strong route should compute"),
            Some(door_position)
        );
        let mut restored =
            WorldState::from_snapshot(&strong.snapshot()).expect("strong route should restore");
        let strong_outcome = strong
            .advance_tick(Vec::new())
            .expect("strong route bash should advance");
        assert_eq!(
            strong_outcome,
            restored
                .advance_tick(Vec::new())
                .expect("restored route bash should advance")
        );
        assert!(matches!(
            strong_outcome.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CreatureBashed {
                    creature_id,
                    target: event_target,
                    target_kind: BashTargetKindV1::Terrain,
                    target_type_id,
                    success: true,
                    ..
                },
                ..
            }] if *creature_id == strong_id
                && *event_target == door_position
                && target_type_id == "t_door_c"
        ));
        assert_eq!(
            strong.canonical_hash().expect("strong world should hash"),
            restored
                .canonical_hash()
                .expect("restored world should hash")
        );

        let mut blocked = base.clone();
        let blocker_position = WorldPosition { x: 4, y: 4, z: 0 };
        let (blocker_coord, blocker_local) = blocker_position.chunk_and_local();
        blocked
            .chunks
            .get_mut(&blocker_coord)
            .expect("blocker chunk should remain")
            .set_furniture(
                blocker_local,
                Some(FurnitureTileSnapshot {
                    blocks_door: true,
                    ..test_furniture("f_door_blocker", 0, true)
                }),
            )
            .expect("door blocker should install");
        let blocked_id = spawn(&mut blocked, 10, 10, false);
        assert_eq!(
            blocked
                .creature_route_bash_rating(blocked_id, door_position)
                .expect("blocked route estimate should compute"),
            Some(10),
            "route estimates use ordinary bounds like upstream bash_rating_internal"
        );
        let blocked_outcome = blocked
            .advance_tick(Vec::new())
            .expect("blocked route bash should advance");
        assert!(matches!(
            blocked_outcome.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CreatureBashed {
                    creature_id,
                    target: event_target,
                    success: false,
                    damage: 0,
                    ..
                },
                ..
            }] if *creature_id == blocked_id && *event_target == door_position
        ));

        let mut desperate = base;
        let desperate_id = spawn(&mut desperate, 2, 4, true);
        assert_eq!(
            desperate
                .creature_route_bash_rating(desperate_id, door_position)
                .expect("base route rating should compute"),
            Some(1)
        );
        assert_eq!(
            desperate
                .creature_bash_rating(desperate_id, door_position)
                .expect("direct group estimate should compute"),
            Some(3)
        );
        assert_eq!(
            desperate
                .creature_route_tile_cost(
                    desperate_id,
                    desperate
                        .creatures
                        .get(&desperate_id)
                        .expect("desperate basher"),
                    door_position,
                )
                .expect("desperate route cost should compute"),
            Some(500)
        );
        let detour_step = desperate
            .creature_route_step(desperate_id, from, target)
            .expect("desperate route should compute")
            .expect("detour should exist");
        assert_ne!(detour_step, door_position);
        let desperate_outcome = desperate
            .advance_tick(Vec::new())
            .expect("desperate detour should advance");
        assert!(matches!(
            desperate_outcome.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CreatureMoved {
                    creature_id,
                    from: event_from,
                    to,
                },
                ..
            }] if *creature_id == desperate_id
                && *event_from == from
                && *to == detour_step
        ));
    }

    #[test]
    fn opaque_terrain_rejects_a_shot_without_spending_ammunition() {
        let mut world = WorldState::new(16, [10; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        chunk
            .set_terrain(
                LocalTileCoord { x: 3, y: 1 },
                TerrainTileSnapshot {
                    terrain_id: String::from("t_wall"),
                    move_cost: 0,
                    transparent: false,
                    flat: false,
                    open: String::new(),
                    open_move_cost: None,
                    open_transparent: None,
                    open_flat: None,
                    close: String::new(),
                    close_move_cost: None,
                    close_transparent: None,
                    close_flat: None,
                },
            )
            .expect("wall should be valid");
        world.insert_chunk(chunk);
        let actor = world
            .spawn_actor(WorldPosition { x: 1, y: 1, z: 0 }, true)
            .expect("actor should spawn");
        make_actor_act_each_tick(&mut world, actor);
        let weapon = world
            .spawn_ground_item(ItemSpawn {
                position: WorldPosition { x: 1, y: 1, z: 0 },
                type_id: String::from("test_revolver"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: Some(RangedWeaponSnapshot {
                    ammunition_type: String::from("38"),
                    ammunition_remaining: 2,
                    ammunition_capacity: 6,
                    range: 10,
                    damage: 10,
                    dispersion: 0,
                    sound_volume: 0,
                }),
            })
            .expect("weapon should spawn");
        let creature = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_target"),
                position: WorldPosition { x: 5, y: 1, z: 0 },
                hp: 10,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("target should spawn");
        for (index, kind) in [
            CommandKind::PickUp { item_id: weapon },
            CommandKind::Wield { item_id: weapon },
        ]
        .into_iter()
        .enumerate()
        {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence((index + 1) as u64),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("inventory action should advance");
        }
        let rejected = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(3),
                client_tick: world.tick(),
                kind: CommandKind::ShootCreature { target: creature },
            }])
            .expect("blocked shot should resolve");
        assert!(matches!(
            rejected.events[0].kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::NoClearShot,
                ..
            }
        ));
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory[0]
                .ranged_weapon
                .as_ref()
                .expect("weapon remains ranged")
                .ammunition_remaining,
            2
        );
    }

    #[test]
    fn invalid_preloaded_ammunition_does_not_consume_stable_ids() {
        let (mut world, actor, _other) = world_with_two_actors();
        let next_before = world.allocator.next;
        let position = WorldPosition { x: 1, y: 1, z: 0 };
        let result = world.spawn_ground_item_with_preloaded_item_backed_magazines(
            ItemSpawn {
                position,
                type_id: String::from("sealed_cell"),
                charges: 0,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: None,
            },
            vec![IntegralMagazinePocketPrototypeV1 {
                pocket_index: 0,
                pocket_id: String::new(),
                ammunition_type: String::from("battery"),
                capacity: 10,
                rigid: true,
                reloadable: false,
                unloadable: false,
            }],
            Vec::new(),
            None,
            vec![(
                0,
                ItemSpawn {
                    position,
                    type_id: String::new(),
                    charges: 10,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::from("battery"),
                    ranged_weapon: None,
                },
            )],
        );
        assert!(matches!(result, Err(SimError::InvalidItem)));
        assert_eq!(world.allocator.next, next_before);
        assert!(world.ground_items.is_empty());

        make_actor_act_each_tick(&mut world, actor);
        let sealed = world
            .spawn_ground_item_with_preloaded_item_backed_magazines(
                ItemSpawn {
                    position,
                    type_id: String::from("sealed_cell"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                vec![IntegralMagazinePocketPrototypeV1 {
                    pocket_index: 0,
                    pocket_id: String::new(),
                    ammunition_type: String::from("battery"),
                    capacity: 10,
                    rigid: true,
                    reloadable: false,
                    unloadable: false,
                }],
                Vec::new(),
                None,
                vec![(
                    0,
                    ItemSpawn {
                        position,
                        type_id: String::from("battery"),
                        charges: 10,
                        melee_damage_milli: BTreeMap::new(),
                        calories: 0,
                        quench: 0,
                        comestible_type: String::new(),
                        ammunition_type: String::from("battery"),
                        ranged_weapon: None,
                    },
                )],
            )
            .expect("valid sealed cell should spawn atomically");
        let contained = world
            .ground_item_snapshot(sealed)
            .and_then(|ground| {
                ground.item.integral_magazines[0]
                    .loaded_ammunition
                    .as_deref()
                    .map(|ammunition| ammunition.id)
            })
            .expect("sealed cell should own stable ammunition");
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(1),
                client_tick: world.tick(),
                kind: CommandKind::PickUp { item_id: sealed },
            }])
            .expect("sealed cell should be picked up");
        let before_rejection = world.snapshot();
        let rejected = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(2),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: sealed,
                    pocket_index: 0,
                    contained_item: contained,
                },
            }])
            .expect("sealed pocket removal should reject cleanly");
        assert!(rejected.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PocketNotUnloadable,
                ..
            }
        )));
        assert_eq!(world.allocator.next, next_before + 2);
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory,
            before_rejection.actors[0].inventory
        );
        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&sealed))
            .and_then(|item| item.integral_magazines.first_mut())
            .expect("sealed pocket should remain")
            .unloadable = true;
        let before_stale_id = world.snapshot();
        let stale_id = ItemId::new(world.world_namespace, u64::MAX);
        let stale_rejection = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(3),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: sealed,
                    pocket_index: 0,
                    contained_item: stale_id,
                },
            }])
            .expect("stale contained identity should reject cleanly");
        assert!(stale_rejection.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PocketItemMissing,
                ..
            }
        )));
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory,
            before_stale_id.actors[0].inventory
        );

        while world
            .actors
            .get(&actor)
            .expect("actor remains")
            .inventory
            .len()
            < MAX_ACTOR_INVENTORY_ITEMS
        {
            let filler_id = world
                .allocator
                .allocate_item()
                .expect("test inventory IDs should remain available");
            let filler = ItemInstance::from_snapshot(&ItemSnapshot {
                id: filler_id,
                type_id: String::from("rock"),
                charges: 1,
                damage: 0,
                raw_damage: 0,
                fitted: false,
                variant: None,
                snippet: None,
                variables: BTreeMap::new(),
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                temperature: None,
                ammunition_type: String::new(),
                ranged_weapon: None,
                component_provenance: None,
                magazine_capacity: 0,
                integral_magazines: Vec::new(),
                magazine_wells: Vec::new(),
                ammunition_containers: Vec::new(),
                residual_energy_millijoules: 0,
                powered_tool: None,
                creature_corpse: None,
                containment: Default::default(),
            })
            .expect("filler item should be valid");
            world
                .actors
                .get_mut(&actor)
                .expect("actor remains")
                .inventory
                .insert(filler_id, filler);
        }
        let before_full_rejection = world.snapshot();
        let full_rejection = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(4),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: sealed,
                    pocket_index: 0,
                    contained_item: contained,
                },
            }])
            .expect("full inventory removal should reject cleanly");
        assert!(full_rejection.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::InventoryFull,
                ..
            }
        )));
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory,
            before_full_rejection.actors[0].inventory
        );
    }

    #[test]
    fn removing_generalized_contents_unseals_the_physical_pocket() {
        let (mut world, actor_id, _) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor_id);
        let owner_id = world
            .allocator
            .allocate_item()
            .expect("owner ID should allocate");
        let content_id = world
            .allocator
            .allocate_item()
            .expect("content ID should allocate");
        let mut owner_prototype = test_craft_item_prototype("sealed_case");
        owner_prototype.ammunition_containers = vec![AmmunitionContainerPocketPrototypeV1 {
            pocket_index: 0,
            pocket_id: String::from("CONTENTS"),
            capacities: Vec::new(),
            rigid: true,
            access_moves: 1,
            reloadable: false,
            unloadable: true,
            spawn_rules: Some(cdda_protocol::SpawnPocketRulesV1 {
                kind: cdda_protocol::SpawnPocketKindV1::Container,
                max_contains_volume_milliliters: 1,
                magazine_well_volume_milliliters: 0,
                contents_collapsed_by_default: false,
                max_contains_weight_milligrams: 1,
                max_item_volume_milliliters: 1,
                min_item_volume_milliliters: 0,
                max_item_length_millimeters: 1,
                item_restrictions: vec![String::from("note")],
                flag_restrictions: Vec::new(),
                access_moves: 1,
                rigid: true,
                watertight: false,
                transparent: false,
                forbidden: false,
                sealable: true,
            }),
        }];
        let mut non_rigid_efile = owner_prototype.ammunition_containers[0].clone();
        non_rigid_efile.rigid = false;
        let non_rigid_rules = non_rigid_efile
            .spawn_rules
            .as_mut()
            .expect("spawn rules should exist");
        non_rigid_rules.kind = cdda_protocol::SpawnPocketKindV1::EFileStorage;
        non_rigid_rules.rigid = false;
        assert!(matches!(
            validate_ammunition_container_prototype(&non_rigid_efile),
            Err(SimError::InvalidItem)
        ));
        let invalid_rules = |mutate: fn(&mut cdda_protocol::SpawnPocketRulesV1)| {
            let mut pocket = owner_prototype.ammunition_containers[0].clone();
            mutate(
                pocket
                    .spawn_rules
                    .as_mut()
                    .expect("spawn rules should exist"),
            );
            pocket.rigid = pocket
                .spawn_rules
                .as_ref()
                .expect("spawn rules should exist")
                .rigid;
            validate_ammunition_container_prototype(&pocket)
        };
        assert!(matches!(
            invalid_rules(|rules| {
                rules.rigid = false;
                rules.magazine_well_volume_milliliters = rules.max_contains_volume_milliliters;
            }),
            Err(SimError::InvalidItem)
        ));
        assert!(matches!(
            invalid_rules(|rules| {
                rules.max_contains_volume_milliliters = 2;
                rules.magazine_well_volume_milliliters = 1;
            }),
            Err(SimError::InvalidItem)
        ));
        assert!(matches!(
            invalid_rules(|rules| {
                rules.kind = cdda_protocol::SpawnPocketKindV1::EFileStorage;
                rules.contents_collapsed_by_default = true;
            }),
            Err(SimError::InvalidItem)
        ));
        let mut content_prototype = test_craft_item_prototype("note");
        content_prototype.containment = cdda_protocol::ItemContainmentProfileV1 {
            weight_milligrams: 1,
            volume_milliliters: 1,
            longest_side_millimeters: 1,
            ..cdda_protocol::ItemContainmentProfileV1::default()
        };
        let content =
            item_from_craft_prototype(content_id, &content_prototype, SimTick(0)).snapshot();
        let mut owner = item_from_craft_prototype(owner_id, &owner_prototype, SimTick(0));
        owner.ammunition_containers[0].contents.push(content);
        owner.ammunition_containers[0]
            .spawn_state
            .as_mut()
            .expect("spawn state should exist")
            .sealed = true;
        validate_item_snapshot(&owner.snapshot()).expect("sealed owner should be valid");
        let mut impossible_partial = owner.snapshot();
        let partial_rules = &mut impossible_partial.ammunition_containers[0]
            .spawn_state
            .as_mut()
            .expect("spawn state")
            .rules;
        partial_rules.max_contains_volume_milliliters = 2;
        partial_rules.max_contains_weight_milligrams = 2;
        partial_rules.max_item_volume_milliliters = 2;
        assert!(
            matches!(
                validate_item_snapshot(&impossible_partial),
                Err(SimError::InvalidItem)
            ),
            "simulation recovery must reject impossible sealed-partial state"
        );
        world
            .actors
            .get_mut(&actor_id)
            .expect("actor exists")
            .inventory
            .insert(owner_id, owner);
        let mut impossible_recovery = world.snapshot();
        let collapse_state = impossible_recovery.actors[0].inventory[0].ammunition_containers[0]
            .spawn_state
            .as_mut()
            .expect("spawn state");
        collapse_state.rules.contents_collapsed_by_default = true;
        collapse_state.contents_collapsed = false;
        assert!(matches!(
            WorldState::from_snapshot(&impossible_recovery),
            Err(SimError::InvalidItem)
        ));

        let outcome = world
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(1),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: owner_id,
                    pocket_index: 0,
                    contained_item: content_id,
                },
            }])
            .expect("sealed content removal should resolve");
        assert!(outcome.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PocketItemRemoved {
                contained_item,
                ..
            } if contained_item == content_id
        )));
        let actor = world.actor_snapshot(actor_id).expect("actor remains");
        assert!(actor.inventory.iter().any(|item| item.id == content_id));
        let owner = actor
            .inventory
            .iter()
            .find(|item| item.id == owner_id)
            .expect("owner remains");
        let pocket = &owner.ammunition_containers[0];
        assert!(pocket.contents.is_empty());
        assert!(!pocket.spawn_state.as_ref().expect("spawn state").sealed);
    }

    #[test]
    fn ammunition_container_transfers_are_bounded_atomic_and_identity_preserving() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let quiver = world
            .spawn_ground_item_with_ammunition_containers(
                ItemSpawn {
                    position,
                    type_id: String::from("quiver"),
                    charges: 1,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                vec![AmmunitionContainerPocketPrototypeV1 {
                    pocket_index: 2,
                    pocket_id: String::from("QUIVER"),
                    capacities: vec![
                        cdda_protocol::AmmunitionCapacityV1 {
                            ammunition_type: String::from("arrow"),
                            capacity: 6,
                        },
                        cdda_protocol::AmmunitionCapacityV1 {
                            ammunition_type: String::from("bolt"),
                            capacity: 4,
                        },
                    ],
                    rigid: false,
                    access_moves: 20,
                    reloadable: true,
                    unloadable: true,
                    spawn_rules: None,
                }],
            )
            .expect("strict quiver should spawn");
        let spawn_ammunition =
            |world: &mut WorldState, type_id: &str, ammunition_type: &str, charges| {
                world
                    .spawn_ground_item(ItemSpawn {
                        position,
                        type_id: type_id.to_owned(),
                        charges,
                        melee_damage_milli: BTreeMap::new(),
                        calories: 0,
                        quench: 0,
                        comestible_type: String::new(),
                        ammunition_type: ammunition_type.to_owned(),
                        ranged_weapon: None,
                    })
                    .expect("ammunition should spawn")
            };
        let arrows = spawn_ammunition(&mut world, "arrow_wood", "arrow", 10);
        let metal_arrows = spawn_ammunition(&mut world, "arrow_metal", "arrow", 2);
        let bolts = spawn_ammunition(&mut world, "bolt_wood", "bolt", 3);
        let issue = |world: &mut WorldState, sequence, kind| {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(sequence),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("command should advance")
        };
        for (offset, item_id) in [quiver, arrows, metal_arrows, bolts]
            .into_iter()
            .enumerate()
        {
            issue(
                &mut world,
                u64::try_from(offset + 1).expect("small sequence"),
                CommandKind::PickUp { item_id },
            );
        }

        let allocator_before_split = world.allocator.next;
        let partial = issue(
            &mut world,
            5,
            CommandKind::InsertPocketItem {
                owner_item: quiver,
                pocket_index: 2,
                source_item: arrows,
            },
        );
        let nested_split = partial
            .events
            .iter()
            .find_map(|event| match event.kind {
                WorldEventKind::AmmunitionInsertedIntoContainer {
                    source_item,
                    contained_item,
                    transferred: 6,
                    pocket_ammunition: 6,
                    source_charges_remaining: 4,
                    ..
                } if source_item == arrows => Some(contained_item),
                _ => None,
            })
            .expect("partial insertion should expose the split ID");
        assert_ne!(nested_split, arrows);
        assert_eq!(world.allocator.next, allocator_before_split + 1);
        let actor_after_partial = world.actor_snapshot(actor).expect("actor remains");
        assert_eq!(
            actor_after_partial
                .inventory
                .iter()
                .find(|item| item.id == arrows)
                .expect("partial source remains")
                .charges,
            4
        );
        assert_eq!(
            actor_after_partial
                .inventory
                .iter()
                .find(|item| item.id == quiver)
                .expect("quiver remains")
                .ammunition_containers[0]
                .contents[0]
                .id,
            nested_split
        );

        let allocator_before_remove = world.allocator.next;
        issue(
            &mut world,
            6,
            CommandKind::RemovePocketItem {
                owner_item: quiver,
                pocket_index: 2,
                contained_item: nested_split,
            },
        );
        let actor_after_remove = world.actor_snapshot(actor).expect("actor remains");
        assert!(
            actor_after_remove
                .inventory
                .iter()
                .any(|item| item.id == nested_split && item.charges == 6)
        );
        assert!(
            actor_after_remove
                .inventory
                .iter()
                .find(|item| item.id == quiver)
                .expect("quiver remains")
                .ammunition_containers[0]
                .contents
                .is_empty()
        );
        assert_eq!(world.allocator.next, allocator_before_remove);

        issue(
            &mut world,
            7,
            CommandKind::InsertPocketItem {
                owner_item: quiver,
                pocket_index: 2,
                source_item: metal_arrows,
            },
        );
        issue(
            &mut world,
            8,
            CommandKind::InsertPocketItem {
                owner_item: quiver,
                pocket_index: 2,
                source_item: arrows,
            },
        );
        let full_quiver = world.actor_snapshot(actor).expect("actor remains");
        assert_eq!(
            full_quiver
                .inventory
                .iter()
                .find(|item| item.id == quiver)
                .expect("quiver remains")
                .ammunition_containers[0]
                .contents
                .iter()
                .map(|item| (item.id, item.type_id.as_str(), item.charges))
                .collect::<Vec<_>>(),
            vec![(arrows, "arrow_wood", 4), (metal_arrows, "arrow_metal", 2)]
        );
        world
            .actors
            .get_mut(&actor)
            .expect("actor remains")
            .action_points = i64::from(ACTOR_ACTION_THRESHOLD);
        let before_mismatch = world.snapshot();
        let rejected = issue(
            &mut world,
            9,
            CommandKind::InsertPocketItem {
                owner_item: quiver,
                pocket_index: 2,
                source_item: bolts,
            },
        );
        assert!(rejected.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::IncompatibleAmmunition,
                ..
            }
        )));
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory,
            before_mismatch.actors[0].inventory
        );
        assert_eq!(
            world
                .actors
                .get(&actor)
                .expect("actor remains")
                .action_points,
            i64::from(ACTOR_ACTION_THRESHOLD),
            "rejected container transfers cost no action points"
        );

        for (sequence, contained_item) in [(10, arrows), (11, metal_arrows)] {
            issue(
                &mut world,
                sequence,
                CommandKind::RemovePocketItem {
                    owner_item: quiver,
                    pocket_index: 2,
                    contained_item,
                },
            );
        }
        world.actors.get_mut(&actor).expect("actor remains").wielded = Some(bolts);
        issue(
            &mut world,
            12,
            CommandKind::InsertPocketItem {
                owner_item: quiver,
                pocket_index: 2,
                source_item: bolts,
            },
        );
        let switched = world.actor_snapshot(actor).expect("actor remains");
        let switched_pocket = &switched
            .inventory
            .iter()
            .find(|item| item.id == quiver)
            .expect("quiver remains")
            .ammunition_containers[0];
        assert_eq!(switched_pocket.contents.len(), 1);
        assert_eq!(switched_pocket.contents[0].id, bolts);
        assert_eq!(switched_pocket.contents[0].ammunition_type, "bolt");
        assert_eq!(switched.wielded, None);
        WorldState::from_snapshot(&world.snapshot())
            .expect("whole insertion of wielded ammunition must remain recoverable");
    }

    #[test]
    fn integral_magazine_reload_preserves_whole_ids_and_allocates_partial_split_ids() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let spawn_magazine = |world: &mut WorldState, type_id: &str, capacity, reloadable| {
            world
                .spawn_ground_item_with_item_backed_magazines(
                    ItemSpawn {
                        position,
                        type_id: type_id.to_owned(),
                        charges: 0,
                        melee_damage_milli: BTreeMap::new(),
                        calories: 0,
                        quench: 0,
                        comestible_type: String::new(),
                        ammunition_type: String::new(),
                        ranged_weapon: None,
                    },
                    vec![IntegralMagazinePocketPrototypeV1 {
                        pocket_index: 3,
                        pocket_id: String::from("PRIMARY"),
                        ammunition_type: String::from("battery"),
                        capacity,
                        rigid: true,
                        reloadable,
                        unloadable: true,
                    }],
                    Vec::new(),
                    None,
                )
                .expect("integral magazine should spawn")
        };
        let sealed_magazine = spawn_magazine(&mut world, "sealed_cell", 6, false);
        let partial_magazine = spawn_magazine(&mut world, "small_cell", 6, true);
        let whole_magazine = spawn_magazine(&mut world, "large_cell", 20, true);
        let ammunition = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("battery"),
                charges: 10,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::from("battery"),
                ranged_weapon: None,
            })
            .expect("loose ammunition should spawn");
        for (offset, item_id) in [
            sealed_magazine,
            partial_magazine,
            whole_magazine,
            ammunition,
        ]
        .into_iter()
        .enumerate()
        {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(u64::try_from(offset + 1).expect("small sequence")),
                    client_tick: world.tick(),
                    kind: CommandKind::PickUp { item_id },
                }])
                .expect("item should be picked up");
        }
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(5),
                client_tick: world.tick(),
                kind: CommandKind::Wield {
                    item_id: sealed_magazine,
                },
            }])
            .expect("sealed magazine should be wielded");
        let sealed = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(6),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("sealed reload should reject cleanly");
        assert!(sealed.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PocketNotReloadable,
                ..
            }
        )));
        let actor_after_rejection = world.actor_snapshot(actor).expect("actor should remain");
        assert_eq!(
            actor_after_rejection
                .inventory
                .iter()
                .find(|item| item.id == ammunition)
                .expect("source ammunition should remain")
                .charges,
            10
        );
        assert!(
            actor_after_rejection
                .inventory
                .iter()
                .find(|item| item.id == sealed_magazine)
                .expect("sealed magazine should remain")
                .integral_magazines[0]
                .loaded_ammunition
                .is_none()
        );

        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(7),
                client_tick: world.tick(),
                kind: CommandKind::Wield {
                    item_id: partial_magazine,
                },
            }])
            .expect("partial magazine should be wielded");
        let partial = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(8),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("partial reload should succeed");
        let split_id = partial
            .events
            .iter()
            .find_map(|event| match event.kind {
                WorldEventKind::AmmunitionLoadedIntoPocket {
                    source_ammunition,
                    nested_ammunition,
                    loaded: 6,
                    pocket_ammunition: 6,
                    source_charges_remaining: 4,
                    ..
                } if source_ammunition == ammunition => Some(nested_ammunition),
                _ => None,
            })
            .expect("partial reload should report its nested identity");
        assert_ne!(split_id, ammunition);

        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&ammunition))
            .expect("source ammunition should remain")
            .damage = 1;
        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&ammunition))
            .expect("source ammunition should remain")
            .raw_damage = 1;
        let incompatible_merge = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(9),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("differing stack state should reject cleanly");
        assert!(incompatible_merge.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::IncompatibleAmmunition,
                ..
            }
        )));
        {
            let actor_state = world.actors.get_mut(&actor).expect("actor should remain");
            let source = actor_state
                .inventory
                .get_mut(&ammunition)
                .expect("source ammunition should remain");
            source.damage = 0;
            source.raw_damage = 0;
            let pocket = &mut actor_state
                .inventory
                .get_mut(&partial_magazine)
                .expect("partial magazine should remain")
                .integral_magazines[0];
            pocket
                .loaded_ammunition
                .as_deref_mut()
                .expect("nested ammunition should remain")
                .charges = 5;
            pocket.residual_energy_millijoules = 1;
        }
        let next_id_before_residual_rejection = world.allocator.next;
        let residual_full = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(10),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("fractionally full pocket should reject cleanly");
        assert!(residual_full.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::WeaponFull,
                ..
            }
        )));
        assert_eq!(world.allocator.next, next_id_before_residual_rejection);

        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(11),
                client_tick: world.tick(),
                kind: CommandKind::Wield {
                    item_id: whole_magazine,
                },
            }])
            .expect("whole magazine should be wielded");
        let whole = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(12),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("whole-stack reload should succeed");
        assert!(whole.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::AmmunitionLoadedIntoPocket {
                source_ammunition,
                nested_ammunition,
                loaded: 4,
                pocket_ammunition: 4,
                source_charges_remaining: 0,
                ..
            } if source_ammunition == ammunition && nested_ammunition == ammunition
        )));
        let actor_snapshot = world.actor_snapshot(actor).expect("actor should remain");
        assert!(
            !actor_snapshot
                .inventory
                .iter()
                .any(|item| item.id == ammunition)
        );
        let partial = actor_snapshot
            .inventory
            .iter()
            .find(|item| item.id == partial_magazine)
            .expect("partial magazine should remain");
        assert_eq!(
            partial.integral_magazines[0]
                .loaded_ammunition
                .as_deref()
                .expect("split ammunition should be nested")
                .id,
            split_id
        );
        let whole = actor_snapshot
            .inventory
            .iter()
            .find(|item| item.id == whole_magazine)
            .expect("whole magazine should remain");
        assert_eq!(
            whole.integral_magazines[0]
                .loaded_ammunition
                .as_deref()
                .expect("whole ammunition should be nested")
                .id,
            ammunition
        );
        let next_before_unload = world.allocator.next;
        let unloaded = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(13),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: whole_magazine,
                    pocket_index: 3,
                    contained_item: ammunition,
                },
            }])
            .expect("whole nested stack should unload");
        assert!(unloaded.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PocketItemRemoved {
                owner_item,
                pocket_index: 3,
                contained_item,
                charges: 4,
                ..
            } if owner_item == whole_magazine && contained_item == ammunition
        )));
        assert_eq!(world.allocator.next, next_before_unload);
        let after_unload = world.actor_snapshot(actor).expect("actor should remain");
        assert_eq!(
            after_unload
                .inventory
                .iter()
                .find(|item| item.id == ammunition)
                .expect("unloaded stack should retain its ID")
                .charges,
            4
        );
        assert!(
            after_unload
                .inventory
                .iter()
                .find(|item| item.id == whole_magazine)
                .expect("whole magazine should remain")
                .integral_magazines[0]
                .loaded_ammunition
                .is_none()
        );
        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&ammunition))
            .expect("unloaded ammunition should remain mutable")
            .residual_energy_millijoules = 123_456;
        let reloaded_whole = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(14),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("unloaded stack should reload with the same ID");
        assert!(reloaded_whole.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::AmmunitionLoadedIntoPocket {
                source_ammunition,
                nested_ammunition,
                loaded: 4,
                pocket_ammunition: 4,
                pocket_residual_energy_millijoules: 123_456,
                source_charges_remaining: 0,
                source_residual_energy_millijoules_remaining: 0,
                ..
            } if source_ammunition == ammunition && nested_ammunition == ammunition
        )));
        assert!(
            world
                .actor_snapshot(actor)
                .expect("actor should remain")
                .inventory
                .iter()
                .find(|item| item.id == whole_magazine)
                .expect("whole magazine should remain")
                .integral_magazines[0]
                .loaded_ammunition
                .as_deref()
                .is_some_and(|nested| nested.id == ammunition && nested.charges == 4)
        );
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor should remain")
                .inventory
                .iter()
                .find(|item| item.id == whole_magazine)
                .expect("whole magazine should remain")
                .integral_magazines[0]
                .residual_energy_millijoules,
            123_456
        );
        let mut disassembly = test_disassembly_recipe(100, 0, Vec::new());
        disassembly.target_type_id = String::from("small_cell");
        let rejected_disassembly = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(15),
                client_tick: world.tick(),
                kind: CommandKind::Disassemble {
                    item_id: partial_magazine,
                    item_type_id: String::from("small_cell"),
                    recipe: Some(Box::new(disassembly)),
                },
            }])
            .expect("loaded item-backed magazine disassembly should reject cleanly");
        assert!(rejected_disassembly.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::DisassemblyUnavailable,
                ..
            }
        )));
        assert!(
            world
                .actor_snapshot(actor)
                .expect("actor should remain")
                .inventory
                .iter()
                .find(|item| item.id == partial_magazine)
                .expect("rejected target should remain")
                .integral_magazines[0]
                .loaded_ammunition
                .is_some()
        );
        let constrained_magazine = world
            .spawn_ground_item_with_item_backed_magazines(
                ItemSpawn {
                    position,
                    type_id: String::from("constrained_cell"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                vec![IntegralMagazinePocketPrototypeV1 {
                    pocket_index: 3,
                    pocket_id: String::from("PRIMARY"),
                    ammunition_type: String::from("battery"),
                    capacity: 4,
                    rigid: true,
                    reloadable: true,
                    unloadable: true,
                }],
                Vec::new(),
                None,
            )
            .expect("constrained magazine should spawn");
        let fractional_source = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("battery"),
                charges: 4,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::from("battery"),
                ranged_weapon: None,
            })
            .expect("fractional source should spawn");
        for (sequence, item_id) in [(16, constrained_magazine), (17, fractional_source)] {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(sequence),
                    client_tick: world.tick(),
                    kind: CommandKind::PickUp { item_id },
                }])
                .expect("constrained split fixture should be picked up");
        }
        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&fractional_source))
            .expect("fractional source should be carried")
            .residual_energy_millijoules = 123_456;
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(18),
                client_tick: world.tick(),
                kind: CommandKind::Wield {
                    item_id: constrained_magazine,
                },
            }])
            .expect("constrained magazine should be wielded");
        let allocator_before_constrained_split = world.allocator.next;
        let constrained_split = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(19),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: fractional_source,
                    target_pocket_index: Some(3),
                },
            }])
            .expect("whole charges should split away from retained fractional energy");
        let nested_split = constrained_split
            .events
            .iter()
            .find_map(|event| match event.kind {
                WorldEventKind::AmmunitionLoadedIntoPocket {
                    source_ammunition,
                    nested_ammunition,
                    loaded: 4,
                    pocket_ammunition: 4,
                    pocket_residual_energy_millijoules: 0,
                    source_charges_remaining: 0,
                    source_residual_energy_millijoules_remaining: 123_456,
                    ..
                } if source_ammunition == fractional_source => Some(nested_ammunition),
                _ => None,
            })
            .expect("constrained split should report both retained identities");
        assert_ne!(nested_split, fractional_source);
        assert_eq!(world.allocator.next, allocator_before_constrained_split + 1);
        let constrained_snapshot = world.actor_snapshot(actor).expect("actor should remain");
        let loose_fraction = constrained_snapshot
            .inventory
            .iter()
            .find(|item| item.id == fractional_source)
            .expect("residual-only source should remain loose");
        assert_eq!(loose_fraction.charges, 0);
        assert_eq!(loose_fraction.residual_energy_millijoules, 123_456);
        let constrained_pocket = &constrained_snapshot
            .inventory
            .iter()
            .find(|item| item.id == constrained_magazine)
            .expect("constrained magazine should remain")
            .integral_magazines[0];
        assert_eq!(constrained_pocket.residual_energy_millijoules, 0);
        assert_eq!(
            constrained_pocket
                .loaded_ammunition
                .as_deref()
                .expect("whole-charge split should be nested")
                .id,
            nested_split
        );
        WorldState::from_snapshot(&world.snapshot())
            .expect("loose residual-only source should restore exactly");
        let snapshot = world.snapshot();
        for item in &snapshot.actors[0].inventory {
            assert!(
                validate_item_snapshot(item).is_ok(),
                "invalid item after reload: {item:#?}"
            );
        }
        let restored = WorldState::from_snapshot(&snapshot).expect("nested state should restore");
        assert_eq!(
            world.canonical_hash().expect("world should hash"),
            restored
                .canonical_hash()
                .expect("restored world should hash")
        );

        let mut duplicate = snapshot;
        let inventory = &mut duplicate.actors[0].inventory;
        let partial_index = inventory
            .iter()
            .position(|item| item.id == partial_magazine)
            .expect("partial magazine should be present");
        inventory[partial_index].integral_magazines[0]
            .loaded_ammunition
            .as_deref_mut()
            .expect("nested ammunition should exist")
            .id = whole_magazine;
        assert!(matches!(
            WorldState::from_snapshot(&duplicate),
            Err(SimError::InvalidSnapshot)
        ));
    }

    #[test]
    fn item_backed_battery_powers_a_detachable_tool_and_retains_fractional_energy() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let tool = world
            .spawn_ground_item_with_powered_magazine_wells(
                ItemSpawn {
                    position,
                    type_id: String::from("test_light"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                0,
                vec![MagazineWellPrototypeV1 {
                    pocket_index: 1,
                    pocket_id: String::from("POWER"),
                    compatible_magazine_type_ids: vec![String::from("test_cell")],
                    rigid: true,
                    unloadable: true,
                }],
                0,
                Some(PoweredToolStateV1 {
                    inactive_type_id: String::from("test_light"),
                    active_type_id: String::from("test_light_on"),
                    activation_charges: 1,
                    power_draw_milliwatts: 1_000,
                    light_emission: 4,
                    dims_with_charge: false,
                    power_pocket_index: 1,
                    active: false,
                }),
            )
            .expect("powered tool should spawn");
        let cell = world
            .spawn_ground_item_with_item_backed_magazines(
                ItemSpawn {
                    position,
                    type_id: String::from("test_cell"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                vec![
                    IntegralMagazinePocketPrototypeV1 {
                        pocket_index: 0,
                        pocket_id: String::from("PRIMARY"),
                        ammunition_type: String::from("battery"),
                        capacity: 1,
                        rigid: true,
                        reloadable: true,
                        unloadable: true,
                    },
                    IntegralMagazinePocketPrototypeV1 {
                        pocket_index: 2,
                        pocket_id: String::from("RESERVE"),
                        ammunition_type: String::from("battery"),
                        capacity: 1,
                        rigid: true,
                        reloadable: true,
                        unloadable: true,
                    },
                ],
                Vec::new(),
                None,
            )
            .expect("cell should spawn");
        let ammunition = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("battery"),
                charges: 2,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::from("battery"),
                ranged_weapon: None,
            })
            .expect("battery ammunition should spawn");
        let ammunition_instance = world
            .ground_items
            .get_mut(&ammunition)
            .expect("spawned battery should remain on the ground");
        ammunition_instance.item.containment.count_by_charges = true;
        ammunition_instance.item.containment.stack_size = 1;
        let commands = [
            CommandKind::PickUp { item_id: tool },
            CommandKind::PickUp { item_id: cell },
            CommandKind::PickUp {
                item_id: ammunition,
            },
            CommandKind::Wield { item_id: cell },
            CommandKind::Reload {
                ammunition_item: ammunition,
                target_pocket_index: Some(0),
            },
            CommandKind::Reload {
                ammunition_item: ammunition,
                target_pocket_index: Some(2),
            },
            CommandKind::Wield { item_id: tool },
            CommandKind::Reload {
                ammunition_item: cell,
                target_pocket_index: Some(1),
            },
            CommandKind::Activate { item_id: tool },
        ];
        let mut last = None;
        for (offset, kind) in commands.into_iter().enumerate() {
            last = Some(
                world
                    .advance_tick(vec![ClientCommand {
                        actor_id: actor,
                        sequence: CommandSequence(
                            u64::try_from(offset + 1).expect("small sequence"),
                        ),
                        client_tick: world.tick(),
                        kind,
                    }])
                    .expect("battery command should resolve"),
            );
        }
        let last = last.expect("commands should produce an outcome");
        assert!(last.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PoweredToolChanged {
                item_id,
                active: true,
                reason: PoweredToolTransitionReason::Activated,
                available_energy_millijoules: 1_000_000,
                ..
            } if item_id == tool
        )));
        for _ in 0..SimTick::HZ {
            world
                .advance_tick(Vec::new())
                .expect("active tool should consume continuous power");
        }
        let tool_snapshot = world
            .actor_snapshot(actor)
            .expect("actor should remain")
            .inventory
            .into_iter()
            .find(|item| item.id == tool)
            .expect("tool should remain");
        let installed = tool_snapshot.magazine_wells[0]
            .installed_magazine
            .as_deref()
            .expect("cell should be installed");
        assert!(installed.integral_magazines[0].loaded_ammunition.is_none());
        let pocket = &installed.integral_magazines[1];
        assert_eq!(
            pocket
                .loaded_ammunition
                .as_deref()
                .expect("depleted stack identity should remain with residual energy")
                .charges,
            0
        );
        assert_eq!(pocket.residual_energy_millijoules, 999_000);
        WorldState::from_snapshot(&world.snapshot())
            .expect("fractional nested battery state should restore");
        let active_rejection = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(10),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: tool,
                    pocket_index: 1,
                    contained_item: cell,
                },
            }])
            .expect("active power well removal should reject cleanly");
        assert!(active_rejection.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PoweredToolActive,
                ..
            }
        )));
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(11),
                client_tick: world.tick(),
                kind: CommandKind::Activate { item_id: tool },
            }])
            .expect("tool should deactivate");
        let removed = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(12),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: tool,
                    pocket_index: 1,
                    contained_item: cell,
                },
            }])
            .expect("inactive power cell should be removable");
        assert!(removed.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PocketItemRemoved {
                owner_item,
                pocket_index: 1,
                contained_item,
                ..
            } if owner_item == tool && contained_item == cell
        )));
        let actor_snapshot = world.actor_snapshot(actor).expect("actor should remain");
        assert!(
            actor_snapshot
                .inventory
                .iter()
                .find(|item| item.id == tool)
                .expect("tool should remain")
                .magazine_wells[0]
                .installed_magazine
                .is_none()
        );
        let removed_cell = actor_snapshot
            .inventory
            .iter()
            .find(|item| item.id == cell)
            .expect("removed cell should retain its stable ID");
        assert_eq!(
            removed_cell.integral_magazines[1].residual_energy_millijoules,
            999_000
        );
        let allocator_before_fractional_round_trip = world.allocator.next;
        let removed_fraction = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(13),
                client_tick: world.tick(),
                kind: CommandKind::RemovePocketItem {
                    owner_item: cell,
                    pocket_index: 2,
                    contained_item: ammunition,
                },
            }])
            .expect("fractionally depleted ammunition should be removable");
        assert!(removed_fraction.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PocketItemRemoved {
                owner_item,
                pocket_index: 2,
                contained_item,
                charges: 0,
                residual_energy_millijoules: 999_000,
                ..
            } if owner_item == cell && contained_item == ammunition
        )));
        let removed_snapshot = world.actor_snapshot(actor).expect("actor should remain");
        let loose_fraction = removed_snapshot
            .inventory
            .iter()
            .find(|item| item.id == ammunition)
            .expect("fractional battery should retain its stable ID as a loose item");
        assert_eq!(loose_fraction.charges, 0);
        assert_eq!(loose_fraction.residual_energy_millijoules, 999_000);
        assert!(
            removed_snapshot
                .inventory
                .iter()
                .find(|item| item.id == cell)
                .expect("cell should remain")
                .integral_magazines[1]
                .loaded_ammunition
                .is_none()
        );
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(14),
                client_tick: world.tick(),
                kind: CommandKind::Wield { item_id: cell },
            }])
            .expect("cell should be wielded for fractional reload");
        let reloaded_fraction = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(15),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: ammunition,
                    target_pocket_index: Some(2),
                },
            }])
            .expect("fractional battery should reload");
        assert!(reloaded_fraction.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::AmmunitionLoadedIntoPocket {
                source_ammunition,
                nested_ammunition,
                loaded: 0,
                pocket_ammunition: 0,
                pocket_residual_energy_millijoules: 999_000,
                source_charges_remaining: 0,
                source_residual_energy_millijoules_remaining: 0,
                ..
            } if source_ammunition == ammunition && nested_ammunition == ammunition
        )));
        let reloaded_snapshot = world.actor_snapshot(actor).expect("actor should remain");
        assert!(
            !reloaded_snapshot
                .inventory
                .iter()
                .any(|item| item.id == ammunition)
        );
        let reloaded_pocket = &reloaded_snapshot
            .inventory
            .iter()
            .find(|item| item.id == cell)
            .expect("cell should remain")
            .integral_magazines[1];
        assert_eq!(reloaded_pocket.residual_energy_millijoules, 999_000);
        assert_eq!(
            reloaded_pocket
                .loaded_ammunition
                .as_deref()
                .expect("fractional stack identity should be nested again")
                .id,
            ammunition
        );
        assert_eq!(world.allocator.next, allocator_before_fractional_round_trip);
    }

    #[test]
    fn two_detachable_wells_reload_by_canonical_pocket_and_restore_nested_ids() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let tool = world
            .spawn_ground_item_with_powered_magazine_wells(
                ItemSpawn {
                    position,
                    type_id: String::from("dual_power_tool_on"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                0,
                vec![
                    MagazineWellPrototypeV1 {
                        pocket_index: 1,
                        pocket_id: String::from("PRIMARY"),
                        compatible_magazine_type_ids: vec![String::from("light_battery")],
                        rigid: true,
                        unloadable: true,
                    },
                    MagazineWellPrototypeV1 {
                        pocket_index: 4,
                        pocket_id: String::from("AUXILIARY"),
                        compatible_magazine_type_ids: vec![String::from("heavy_battery")],
                        rigid: true,
                        unloadable: true,
                    },
                ],
                0,
                Some(PoweredToolStateV1 {
                    inactive_type_id: String::from("dual_power_tool"),
                    active_type_id: String::from("dual_power_tool_on"),
                    activation_charges: 1,
                    power_draw_milliwatts: 1_000,
                    light_emission: 4,
                    dims_with_charge: false,
                    power_pocket_index: 1,
                    active: true,
                }),
            )
            .expect("two-well tool should spawn");
        let mut spawn_magazine = |type_id: &str| {
            world
                .spawn_ground_item_with_magazine_storage(
                    ItemSpawn {
                        position,
                        type_id: type_id.to_owned(),
                        charges: 3,
                        melee_damage_milli: BTreeMap::new(),
                        calories: 0,
                        quench: 0,
                        comestible_type: String::new(),
                        ammunition_type: String::from("battery"),
                        ranged_weapon: None,
                    },
                    10,
                    None,
                )
                .expect("magazine should spawn")
        };
        let primary = spawn_magazine("light_battery");
        let auxiliary = spawn_magazine("heavy_battery");
        for (index, item_id) in [tool, primary, auxiliary].into_iter().enumerate() {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(u64::try_from(index + 1).expect("small index")),
                    client_tick: world.tick(),
                    kind: CommandKind::PickUp { item_id },
                }])
                .expect("item should be picked up");
        }
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(4),
                client_tick: world.tick(),
                kind: CommandKind::Wield { item_id: tool },
            }])
            .expect("tool should be wielded");
        let missing = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(5),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: primary,
                    target_pocket_index: Some(2),
                },
            }])
            .expect("missing pocket should reject");
        assert!(missing.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PocketMissing,
                ..
            }
        )));
        let blocked_power_reload = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(6),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: primary,
                    target_pocket_index: Some(1),
                },
            }])
            .expect("active power-pocket reload should reject");
        assert!(blocked_power_reload.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::PoweredToolActive,
                ..
            }
        )));
        let auxiliary_reload = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(7),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: auxiliary,
                    target_pocket_index: Some(4),
                },
            }])
            .expect("an auxiliary well should reload while the tool is active");
        assert!(auxiliary_reload.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::MagazineReloaded {
                tool: event_tool,
                magazine: event_magazine,
                magazine_well_index: 4,
                ..
            } if event_tool == tool && event_magazine == auxiliary
        )));
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(8),
                client_tick: world.tick(),
                kind: CommandKind::Activate { item_id: tool },
            }])
            .expect("active tool should deactivate without consuming power");
        let primary_reload = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(9),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: primary,
                    target_pocket_index: Some(1),
                },
            }])
            .expect("inactive power pocket should reload");
        assert!(primary_reload.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::MagazineReloaded {
                tool: event_tool,
                magazine: event_magazine,
                magazine_well_index: 1,
                ..
            } if event_tool == tool && event_magazine == primary
        )));
        let snapshot = world.snapshot();
        let tool_snapshot = snapshot
            .actors
            .iter()
            .find(|snapshot| snapshot.id == actor)
            .and_then(|snapshot| snapshot.inventory.iter().find(|item| item.id == tool))
            .expect("tool should remain carried");
        assert_eq!(
            tool_snapshot
                .magazine_wells
                .iter()
                .map(|well| {
                    (
                        well.pocket_index,
                        well.pocket_id.as_str(),
                        well.installed_magazine.as_deref().map(|item| item.id),
                    )
                })
                .collect::<Vec<_>>(),
            [
                (1, "PRIMARY", Some(primary)),
                (4, "AUXILIARY", Some(auxiliary)),
            ]
        );
        let mut restored = WorldState::from_snapshot(&snapshot).expect("nested IDs should restore");
        assert_eq!(restored.snapshot(), snapshot);
        assert_eq!(
            restored
                .canonical_hash()
                .expect("restored state should hash"),
            world.canonical_hash().expect("original state should hash")
        );

        let mut disassembly = test_disassembly_recipe(100, 0, Vec::new());
        disassembly.target_type_id = String::from("dual_power_tool");
        restored
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(10),
                client_tick: restored.tick(),
                kind: CommandKind::Disassemble {
                    item_id: tool,
                    item_type_id: disassembly.target_type_id.clone(),
                    recipe: Some(Box::new(disassembly)),
                },
            }])
            .expect("multi-well disassembly should start");
        let disassembling = restored.snapshot();
        let detached_ids = disassembling
            .ground_items
            .iter()
            .map(|ground| ground.item.id)
            .collect::<BTreeSet<_>>();
        assert!(detached_ids.contains(&primary));
        assert!(detached_ids.contains(&auxiliary));
        assert!(
            disassembling
                .actors
                .iter()
                .find(|candidate| candidate.id == actor)
                .and_then(|actor| actor.disassembly_activity.as_ref())
                .is_some_and(|activity| activity
                    .target_item
                    .magazine_wells
                    .iter()
                    .all(|well| well.installed_magazine.is_none()))
        );
    }

    #[test]
    fn detachable_battery_reload_power_use_disassembly_and_recovery_preserve_identity() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let well = MagazineWellPrototypeV1 {
            pocket_index: 0,
            pocket_id: String::new(),
            compatible_magazine_type_ids: vec![String::from("medium_battery")],
            rigid: true,
            unloadable: true,
        };
        assert!(matches!(
            world.spawn_ground_item_with_powered_storage(
                ItemSpawn {
                    position,
                    type_id: String::from("medium_battery"),
                    charges: 10,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::from("battery"),
                    ranged_weapon: None,
                },
                10,
                None,
                1,
                None,
            ),
            Err(SimError::InvalidItem)
        ));
        let tool = world
            .spawn_ground_item_with_magazine_storage(
                ItemSpawn {
                    position,
                    type_id: String::from("powered_tool"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                0,
                Some(well),
            )
            .expect("tool should spawn");
        let mut spawn_battery = |type_id: &str, charges: i32| {
            world
                .spawn_ground_item_with_magazine_storage(
                    ItemSpawn {
                        position,
                        type_id: type_id.to_owned(),
                        charges,
                        melee_damage_milli: BTreeMap::new(),
                        calories: 0,
                        quench: 0,
                        comestible_type: String::new(),
                        ammunition_type: String::from("battery"),
                        ranged_weapon: None,
                    },
                    10,
                    None,
                )
                .expect("battery should spawn")
        };
        let first_battery = spawn_battery("medium_battery", 5);
        let second_battery = spawn_battery("medium_battery", 10);
        let incompatible = spawn_battery("heavy_battery", 10);
        let component = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("rock"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: None,
            })
            .expect("component should spawn");
        for (index, item_id) in [tool, first_battery, second_battery, incompatible, component]
            .into_iter()
            .enumerate()
        {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(u64::try_from(index + 1).expect("small index")),
                    client_tick: world.tick(),
                    kind: CommandKind::PickUp { item_id },
                }])
                .expect("item should be picked up");
        }
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(6),
                client_tick: world.tick(),
                kind: CommandKind::Wield { item_id: tool },
            }])
            .expect("tool should be wielded");

        let rejected = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(7),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: incompatible,
                    target_pocket_index: Some(0),
                },
            }])
            .expect("incompatible reload should resolve atomically");
        assert!(rejected.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::IncompatibleAmmunition,
                ..
            }
        )));
        assert!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory
                .iter()
                .any(|item| item.id == incompatible)
        );

        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(8),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: first_battery,
                    target_pocket_index: Some(0),
                },
            }])
            .expect("first battery should install");
        let swapped = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(9),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: second_battery,
                    target_pocket_index: Some(0),
                },
            }])
            .expect("second battery should swap in");
        assert!(swapped.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::MagazineReloaded {
                tool: event_tool,
                magazine,
                ejected_magazine: Some(ejected),
                charges: 10,
                ..
            } if event_tool == tool && magazine == second_battery && ejected == first_battery
        )));
        let actor_state = world.actor_snapshot(actor).expect("actor remains");
        let powered = actor_state
            .inventory
            .iter()
            .find(|item| item.id == tool)
            .expect("tool remains carried");
        assert_eq!(
            powered
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|magazine| (magazine.id, magazine.charges)),
            Some((second_battery, 10))
        );
        assert!(
            actor_state
                .inventory
                .iter()
                .any(|item| item.id == first_battery && item.charges == 5)
        );

        let mut craft = test_craft_recipe(100, 1, vec![vec![("rock", 1, false)]]);
        craft.tools = vec![vec![cdda_protocol::CraftToolRequirementV1 {
            type_id: String::from("powered_tool"),
            amount: 4,
            consumes_charges: true,
        }]];
        let started = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(10),
                client_tick: world.tick(),
                kind: CommandKind::Craft {
                    recipe_id: craft.recipe_id.clone(),
                    recipe: Some(Box::new(craft)),
                },
            }])
            .expect("installed battery should power crafting");
        assert!(started.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CraftToolChargesConsumed {
                item_id,
                charges: 4,
                remaining_charges: 6,
                ..
            } if item_id == tool
        )));
        world
            .advance_tick(Vec::new())
            .expect("short craft should complete");

        let mut disassembly = test_disassembly_recipe(100, 0, Vec::new());
        disassembly.target_type_id = String::from("powered_tool");
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(11),
                client_tick: world.tick(),
                kind: CommandKind::Disassemble {
                    item_id: tool,
                    item_type_id: disassembly.target_type_id.clone(),
                    recipe: Some(Box::new(disassembly)),
                },
            }])
            .expect("disassembly should detach the installed battery");
        let snapshot = world.snapshot();
        let dropped = snapshot
            .ground_items
            .iter()
            .find(|ground| ground.item.id == second_battery)
            .expect("same battery identity should be dropped");
        assert_eq!(dropped.item.charges, 6);
        let activity = snapshot
            .actors
            .iter()
            .find(|candidate| candidate.id == actor)
            .and_then(|actor| actor.disassembly_activity.as_ref())
            .expect("disassembly should be active");
        assert!(
            activity
                .target_item
                .magazine_wells
                .first()
                .is_some_and(|well| well.installed_magazine.is_none())
        );

        let mut hostile = snapshot.clone();
        let installed = hostile
            .ground_items
            .iter()
            .find(|ground| ground.item.id == second_battery)
            .expect("battery should exist")
            .item
            .clone();
        hostile
            .ground_items
            .retain(|ground| ground.item.id != second_battery);
        hostile
            .actors
            .iter_mut()
            .find(|candidate| candidate.id == actor)
            .and_then(|actor| actor.disassembly_activity.as_mut())
            .and_then(|activity| activity.target_item.magazine_wells.first_mut())
            .expect("target well should exist")
            .installed_magazine = Some(Box::new(installed));
        assert!(WorldState::from_snapshot(&hostile).is_err());

        let mut impossible_residual = snapshot.clone();
        let overfilled = impossible_residual
            .ground_items
            .iter_mut()
            .find(|ground| ground.item.id == second_battery)
            .expect("battery should exist");
        overfilled.item.charges =
            i32::try_from(overfilled.item.magazine_capacity).expect("small capacity");
        overfilled.item.residual_energy_millijoules = 1;
        assert!(matches!(
            WorldState::from_snapshot(&impossible_residual),
            Err(SimError::InvalidItem)
        ));

        let mut recovered = WorldState::from_snapshot(&snapshot).expect("snapshot should recover");
        recovered
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(12),
                client_tick: recovered.tick(),
                kind: CommandKind::CancelDisassembly,
            }])
            .expect("disassembly should cancel");
        assert!(recovered.ground_item_snapshot(second_battery).is_some());
        assert!(
            recovered
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory
                .iter()
                .find(|item| item.id == tool)
                .and_then(|item| item.magazine_wells.first())
                .is_some_and(|well| well.installed_magazine.is_none())
        );
    }

    #[test]
    fn powered_flashlight_drains_exact_energy_and_keeps_running_offline_and_on_ground() {
        let (mut world, actor, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor);
        let position = world.actor_snapshot(actor).expect("actor exists").position;
        let flashlight = world
            .spawn_ground_item_with_powered_storage(
                ItemSpawn {
                    position,
                    type_id: String::from("flashlight"),
                    charges: 0,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::new(),
                    ranged_weapon: None,
                },
                0,
                Some(MagazineWellPrototypeV1 {
                    pocket_index: 0,
                    pocket_id: String::new(),
                    compatible_magazine_type_ids: vec![String::from("medium_battery")],
                    rigid: true,
                    unloadable: true,
                }),
                0,
                Some(PoweredToolStateV1 {
                    inactive_type_id: String::from("flashlight"),
                    active_type_id: String::from("flashlight_on"),
                    activation_charges: 1,
                    power_draw_milliwatts: 1_560,
                    light_emission: 300,
                    dims_with_charge: true,
                    power_pocket_index: 0,
                    active: false,
                }),
            )
            .expect("flashlight should spawn");
        let battery = world
            .spawn_ground_item_with_powered_storage(
                ItemSpawn {
                    position,
                    type_id: String::from("medium_battery"),
                    charges: 3,
                    melee_damage_milli: BTreeMap::new(),
                    calories: 0,
                    quench: 0,
                    comestible_type: String::new(),
                    ammunition_type: String::from("battery"),
                    ranged_weapon: None,
                },
                10,
                None,
                0,
                None,
            )
            .expect("battery should spawn");
        for (index, kind) in [
            CommandKind::PickUp {
                item_id: flashlight,
            },
            CommandKind::PickUp { item_id: battery },
            CommandKind::Wield {
                item_id: flashlight,
            },
            CommandKind::Reload {
                ammunition_item: battery,
                target_pocket_index: Some(0),
            },
        ]
        .into_iter()
        .enumerate()
        {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence(u64::try_from(index + 1).expect("small index")),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("flashlight setup should advance");
        }

        world.tick = SimTick(13 * 60 * 60 * SimTick::HZ + 7);
        assert!(
            !world
                .actor_has_detail_light(actor)
                .expect("darkness should resolve")
        );
        let activated = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(5),
                client_tick: world.tick(),
                kind: CommandKind::Activate {
                    item_id: flashlight,
                },
            }])
            .expect("activation should advance");
        assert!(activated.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PoweredToolChanged {
                actor_id: Some(event_actor),
                item_id,
                active: true,
                reason: PoweredToolTransitionReason::Activated,
                available_energy_millijoules: 2_000_000,
            } if event_actor == actor && item_id == flashlight
        )));
        let activated_actor = world.actor_snapshot(actor).expect("actor remains");
        assert_eq!(
            activated_actor.action_points,
            i64::from(ACTOR_ACTION_THRESHOLD),
            "the pinned transform has zero move cost"
        );
        let carried = activated_actor
            .inventory
            .into_iter()
            .find(|item| item.id == flashlight)
            .expect("flashlight remains carried");
        assert_eq!(carried.type_id, "flashlight_on");
        assert_eq!(
            carried
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|battery| (
                    battery.id,
                    battery.charges,
                    battery.residual_energy_millijoules
                )),
            Some((battery, 2, 0)),
            "activation spends exactly one whole upstream charge"
        );
        assert!(
            world
                .actor_has_detail_light(actor)
                .expect("carried flashlight should illuminate the actor")
        );

        world
            .set_connected(actor, false)
            .expect("actor should disconnect");
        while !world.tick().0.is_multiple_of(SimTick::HZ) {
            world
                .advance_tick(Vec::new())
                .expect("offline world should advance");
        }
        let carried = world
            .actor_snapshot(actor)
            .expect("disconnected actor remains")
            .inventory
            .into_iter()
            .find(|item| item.id == flashlight)
            .expect("flashlight remains carried");
        assert_eq!(
            carried
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|battery| (battery.charges, battery.residual_energy_millijoules)),
            Some((1, 998_440)),
            "one second consumes exactly 1,560 millijoules while disconnected"
        );

        world
            .set_connected(actor, true)
            .expect("actor should reconnect");
        let active_reload = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(6),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: battery,
                    target_pocket_index: Some(0),
                },
            }])
            .expect("active reload should resolve");
        assert!(active_reload.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                actor_id: event_actor,
                reason: CommandRejection::PoweredToolActive,
                ..
            } if event_actor == actor
        )));
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(7),
                client_tick: world.tick(),
                kind: CommandKind::Activate {
                    item_id: flashlight,
                },
            }])
            .expect("manual deactivation should advance");
        assert!(
            !world
                .actor_has_detail_light(actor)
                .expect("inactive flashlight should not emit")
        );
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(8),
                client_tick: world.tick(),
                kind: CommandKind::Activate {
                    item_id: flashlight,
                },
            }])
            .expect("reactivation should spend the last whole charge");
        let reactivated = world
            .actor_snapshot(actor)
            .expect("actor remains")
            .inventory
            .into_iter()
            .find(|item| item.id == flashlight)
            .expect("flashlight remains carried");
        assert_eq!(
            reactivated
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|battery| (battery.charges, battery.residual_energy_millijoules)),
            Some((0, 998_440)),
            "deactivation is free and reactivation spends one whole charge"
        );
        world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(9),
                client_tick: world.tick(),
                kind: CommandKind::Drop {
                    item_id: flashlight,
                },
            }])
            .expect("active flashlight should drop");
        assert!(world.ground_item_snapshot(flashlight).is_some());
        assert!(
            world
                .actor_has_detail_light(actor)
                .expect("ground flashlight should illuminate the actor")
        );
        world
            .set_connected(actor, false)
            .expect("actor should disconnect again");

        let snapshot = world.snapshot();
        let expected_hash = world.canonical_hash().expect("state should hash");
        let mut recovered = WorldState::from_snapshot(&snapshot).expect("state should recover");
        assert_eq!(
            recovered.canonical_hash().expect("recovery should hash"),
            expected_hash
        );
        while !world.tick().next().0.is_multiple_of(SimTick::HZ) {
            world
                .advance_tick(Vec::new())
                .expect("original should advance");
            recovered
                .advance_tick(Vec::new())
                .expect("recovered should advance");
        }
        let original = world
            .advance_tick(Vec::new())
            .expect("original boundary should advance");
        let replayed = recovered
            .advance_tick(Vec::new())
            .expect("recovered boundary should advance");
        assert_eq!(original.canonical_hash, replayed.canonical_hash);
        assert_eq!(world.snapshot(), recovered.snapshot());
        let ground = world
            .ground_item_snapshot(flashlight)
            .expect("flashlight remains on the ground");
        assert_eq!(
            ground
                .item
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|battery| battery.residual_energy_millijoules),
            Some(996_880),
            "ground tools drain at the same persistent-server rate"
        );

        world.tick = SimTick(13 * 60 * 60 * SimTick::HZ + SimTick::HZ - 1);
        world
            .ground_items
            .get_mut(&flashlight)
            .and_then(|ground| {
                ground
                    .item
                    .magazine_wells
                    .first_mut()
                    .and_then(|well| well.installed_magazine.as_deref_mut())
            })
            .expect("installed battery remains nested")
            .residual_energy_millijoules = 1_560;
        world
            .advance_tick(Vec::new())
            .expect("exact final powered second should advance");
        let final_paid_second = world
            .ground_item_snapshot(flashlight)
            .expect("flashlight remains for its final paid second");
        assert!(
            final_paid_second
                .item
                .powered_tool
                .as_ref()
                .expect("powered state remains")
                .active
        );
        assert_eq!(
            final_paid_second
                .item
                .magazine_wells
                .first()
                .and_then(|well| well.installed_magazine.as_deref())
                .map(|battery| battery.residual_energy_millijoules),
            Some(0)
        );
        assert!(
            !world
                .actor_has_detail_light(actor)
                .expect("zero stored energy should stop emission"),
            "the transform remains active until the next boundary but emits no free light"
        );

        world.tick = SimTick(13 * 60 * 60 * SimTick::HZ + 2 * SimTick::HZ - 1);
        world
            .ground_items
            .get_mut(&flashlight)
            .and_then(|ground| {
                ground
                    .item
                    .magazine_wells
                    .first_mut()
                    .and_then(|well| well.installed_magazine.as_deref_mut())
            })
            .expect("installed battery remains nested")
            .residual_energy_millijoules = 1_559;
        let depleted = world
            .advance_tick(Vec::new())
            .expect("depletion boundary should advance");
        assert!(depleted.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::PoweredToolChanged {
                actor_id: None,
                item_id,
                active: false,
                reason: PoweredToolTransitionReason::EnergyDepleted,
                available_energy_millijoules: 1_559,
            } if item_id == flashlight
        )));
        let depleted_tool = world
            .ground_item_snapshot(flashlight)
            .expect("depleted flashlight remains");
        assert_eq!(depleted_tool.item.type_id, "flashlight");
        assert!(
            !depleted_tool
                .item
                .powered_tool
                .as_ref()
                .expect("powered state remains")
                .active
        );
        assert!(
            !world
                .actor_has_detail_light(actor)
                .expect("depleted light should no longer illuminate")
        );
    }

    #[test]
    fn reload_uses_only_compatible_carried_ammunition() {
        let mut world = WorldState::new(18, [12; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        world.insert_chunk(Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 }));
        let position = WorldPosition { x: 1, y: 1, z: 0 };
        let actor = world
            .spawn_actor(position, true)
            .expect("actor should spawn");
        make_actor_act_each_tick(&mut world, actor);
        let weapon = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("test_revolver"),
                charges: 1,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: Some(RangedWeaponSnapshot {
                    ammunition_type: String::from("38"),
                    ammunition_remaining: 5,
                    ammunition_capacity: 6,
                    range: 10,
                    damage: 1,
                    dispersion: 0,
                    sound_volume: 0,
                }),
            })
            .expect("weapon should spawn");
        let compatible = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("38_special"),
                charges: 2,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::from("38"),
                ranged_weapon: None,
            })
            .expect("compatible ammunition should spawn");
        let incompatible = world
            .spawn_ground_item(ItemSpawn {
                position,
                type_id: String::from("9mm"),
                charges: 4,
                melee_damage_milli: BTreeMap::new(),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::from("9mm"),
                ranged_weapon: None,
            })
            .expect("incompatible ammunition should spawn");
        let target = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_target"),
                position: WorldPosition { x: 4, y: 1, z: 0 },
                hp: 100,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("target should spawn");

        let commands = [
            CommandKind::PickUp { item_id: weapon },
            CommandKind::PickUp {
                item_id: compatible,
            },
            CommandKind::PickUp {
                item_id: incompatible,
            },
            CommandKind::Wield { item_id: weapon },
            CommandKind::ShootCreature { target },
            CommandKind::Reload {
                ammunition_item: compatible,
                target_pocket_index: None,
            },
        ];
        let mut reload_events = Vec::new();
        for (index, kind) in commands.into_iter().enumerate() {
            reload_events = world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence((index + 1) as u64),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("inventory and ranged actions should advance")
                .events;
        }
        assert!(reload_events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::WeaponReloaded {
                actor_id,
                weapon: event_weapon,
                ammunition_item,
                loaded: 2,
                ammunition_remaining: 6,
                source_charges_remaining: 0,
            } if actor_id == actor && event_weapon == weapon && ammunition_item == compatible
        )));
        let actor_snapshot = world.actor_snapshot(actor).expect("actor remains");
        assert!(
            !actor_snapshot
                .inventory
                .iter()
                .any(|item| item.id == compatible)
        );
        assert_eq!(
            actor_snapshot
                .inventory
                .iter()
                .find(|item| item.id == weapon)
                .and_then(|item| item.ranged_weapon.as_ref())
                .expect("weapon remains ranged")
                .ammunition_remaining,
            6
        );

        for (sequence, kind) in [
            CommandKind::ShootCreature { target },
            CommandKind::Reload {
                ammunition_item: incompatible,
                target_pocket_index: None,
            },
        ]
        .into_iter()
        .enumerate()
        {
            reload_events = world
                .advance_tick(vec![ClientCommand {
                    actor_id: actor,
                    sequence: CommandSequence((sequence + 7) as u64),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("incompatible reload should resolve")
                .events;
        }
        assert!(reload_events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::IncompatibleAmmunition,
                ..
            }
        )));
        let actor_snapshot = world.actor_snapshot(actor).expect("actor remains");
        assert_eq!(
            actor_snapshot
                .inventory
                .iter()
                .find(|item| item.id == weapon)
                .and_then(|item| item.ranged_weapon.as_ref())
                .expect("weapon remains ranged")
                .ammunition_remaining,
            5
        );
        assert_eq!(
            actor_snapshot
                .inventory
                .iter()
                .find(|item| item.id == incompatible)
                .expect("incompatible ammunition remains")
                .charges,
            4
        );
        {
            let fractional = world
                .actors
                .get_mut(&actor)
                .and_then(|actor| actor.inventory.get_mut(&incompatible))
                .expect("candidate ammunition should remain");
            fractional.ammunition_type = String::from("battery");
            fractional.residual_energy_millijoules = 123_456;
        }
        world
            .actors
            .get_mut(&actor)
            .and_then(|actor| actor.inventory.get_mut(&weapon))
            .and_then(|weapon| weapon.ranged_weapon.as_mut())
            .expect("weapon should remain ranged")
            .ammunition_type = String::from("battery");
        let before_fractional_rejection = world.actor_snapshot(actor).expect("actor remains");
        let fractional_rejection = world
            .advance_tick(vec![ClientCommand {
                actor_id: actor,
                sequence: CommandSequence(9),
                client_tick: world.tick(),
                kind: CommandKind::Reload {
                    ammunition_item: incompatible,
                    target_pocket_index: None,
                },
            }])
            .expect("legacy ranged storage must reject fractional ammunition");
        assert!(fractional_rejection.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CommandRejected {
                reason: CommandRejection::IncompatibleAmmunition,
                ..
            }
        )));
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor remains")
                .inventory,
            before_fractional_rejection.inventory
        );
        WorldState::from_snapshot(&world.snapshot()).expect("reload state should round trip");
    }

    #[test]
    fn disconnected_autopilot_flees_a_visible_hostile_deterministically() {
        let mut world = WorldState::new(17, [11; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        world.insert_chunk(Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 }));
        let actor = world
            .spawn_actor(WorldPosition { x: 0, y: 0, z: 0 }, false)
            .expect("offline actor should spawn");
        let creature = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_slow_test"),
                position: WorldPosition { x: 1, y: 0, z: 0 },
                hp: 20,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 100,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 2,
                melee_dice_sides: 3,
                can_see: true,
                vision_day: 60,
                vision_night: 60,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("hostile creature should spawn");
        let chunks_before = world.chunks.len();
        let mut replay = world.clone();
        let fled = world
            .advance_tick(Vec::new())
            .expect("autopilot should flee");
        let replay_fled = replay
            .advance_tick(Vec::new())
            .expect("autopilot replay should flee");
        assert_eq!(fled, replay_fled);
        assert!(matches!(
            fled.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::ActorMoved { actor_id, from, to },
                ..
            }] if *actor_id == actor
                && *from == (WorldPosition { x: 0, y: 0, z: 0 })
                && *to == (WorldPosition { x: 0, y: 1, z: 0 })
        ));
        assert_eq!(world.chunks.len(), chunks_before);
        assert_eq!(
            world
                .creature_snapshot(creature)
                .expect("creature remains")
                .hp,
            20,
            "fleeing must never initiate combat"
        );
        WorldState::from_snapshot(&world.snapshot()).expect("autopilot state should round trip");
        world
            .set_connected(actor, true)
            .expect("reconnection should succeed");
        world
            .actors
            .get_mut(&actor)
            .expect("actor should remain")
            .action_points = i64::from(ACTOR_ACTION_THRESHOLD);
        let connected_position = world
            .actor_snapshot(actor)
            .expect("actor should remain")
            .position;
        world
            .advance_tick(Vec::new())
            .expect("connected boundary should advance");
        assert_eq!(
            world
                .actor_snapshot(actor)
                .expect("actor should remain")
                .position,
            connected_position,
            "reconnection must return control before another autopilot action"
        );
    }

    #[test]
    fn armed_actor_smashing_is_diagonal_layered_fail_closed_and_replay_stable() {
        let (mut world, actor_id, _other) = world_with_two_actors();
        make_actor_act_each_tick(&mut world, actor_id);
        let target = WorldPosition { x: 2, y: 2, z: 0 };
        let floor = test_terrain("t_floor");
        let mut door = test_terrain("t_actor_bash_door");
        door.move_cost = 0;
        door.transparent = false;
        world
            .register_terrain_bash_type(TerrainBashTypeV1 {
                terrain_id: door.terrain_id.clone(),
                str_min: 8,
                str_max: 12,
                str_min_blocked: -1,
                str_max_blocked: -1,
                str_min_supported: -1,
                str_max_supported: -1,
                bash_multiplier_millionths: 950_000,
                result: floor,
                drop_source: None,
                hit_field: None,
                destroyed_field: None,
                sound: String::from("crash!"),
                failure_sound: String::from("whump!"),
                sound_volume: 18,
                failure_sound_volume: 12,
            })
            .expect("door bash should register");
        world
            .register_smash_item_type(SmashItemTypeV1 {
                item_type_id: String::from("hammer"),
                bash_damage: 9,
                attack_time_moves: 79,
                melee_to_hit: -1,
            })
            .expect("hammer smash profile should register");
        world
            .register_furniture_bash_type(FurnitureBashTypeV1 {
                furniture_id: String::from("f_actor_bash_table"),
                str_min: 5,
                str_max: 10,
                str_min_blocked: -1,
                str_max_blocked: -1,
                str_min_supported: -1,
                str_max_supported: -1,
                bash_multiplier_millionths: 1_000_000,
                result: None,
                drop_source: None,
                hit_field: None,
                destroyed_field: None,
                sound: String::from("splinter!"),
                failure_sound: String::from("thump!"),
                sound_volume: 15,
                failure_sound_volume: 12,
            })
            .expect("furniture bash should register");
        world
            .register_furniture_bash_presence(String::from("f_unsupported_actor_bash"))
            .expect("unsupported furniture bash presence should register");
        assert_eq!(
            pinned_melee_attack_speed_moves(65, 8, 0).expect("default unarmed speed"),
            60
        );
        assert_eq!(
            pinned_melee_attack_speed_moves(65, 20, 0).expect("high-DEX unarmed speed"),
            54
        );
        assert_eq!(
            pinned_melee_attack_speed_moves(65, 8, 10).expect("skilled unarmed speed"),
            38
        );
        assert_eq!(
            pinned_melee_attack_speed_moves(65, 100, 10).expect("effective DEX cap"),
            32,
            "pinned effective character stats cap at 20"
        );
        assert_eq!(
            pinned_melee_attack_speed_moves(1, 20, 10).expect("minimum attack speed"),
            25
        );
        assert_eq!(
            world
                .actor_melee_action_cost(actor_id)
                .expect("unarmed action cost"),
            60 * cdda_protocol::ACTION_POINTS_PER_UPSTREAM_MOVE,
            "the pinned null item has attack time 65 before skill and DEX"
        );
        let (coord, local) = target.chunk_and_local();
        let unsupported_target = WorldPosition { x: 1, y: 0, z: 0 };
        let (unsupported_coord, unsupported_local) = unsupported_target.chunk_and_local();
        assert_eq!(coord, unsupported_coord);
        let chunk = world.chunks.get_mut(&coord).expect("target chunk exists");
        chunk
            .set_terrain(local, door.clone())
            .expect("door should install");
        chunk
            .set_furniture(local, Some(test_furniture("f_actor_bash_table", -1, false)))
            .expect("table should install above the door");
        chunk
            .set_terrain(unsupported_local, door)
            .expect("underlying door should install");
        chunk
            .set_furniture(
                unsupported_local,
                Some(test_furniture("f_unsupported_actor_bash", -1, false)),
            )
            .expect("unsupported bash furniture should install above the door");

        let hammer_id = world
            .spawn_ground_item(ItemSpawn {
                position: world
                    .actor_snapshot(actor_id)
                    .expect("actor exists")
                    .position,
                type_id: String::from("hammer"),
                charges: 1,
                melee_damage_milli: BTreeMap::from([(String::from("bash"), 9_000)]),
                calories: 0,
                quench: 0,
                comestible_type: String::new(),
                ammunition_type: String::new(),
                ranged_weapon: None,
            })
            .expect("hammer should spawn");
        let unarmed = world
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(1),
                client_tick: world.tick(),
                kind: CommandKind::Smash { dx: 1, dy: 1 },
            }])
            .expect("unsupported unarmed smash should resolve");
        assert!(matches!(
            unarmed.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CommandRejected {
                    reason: CommandRejection::InvalidBashTool,
                    ..
                },
                ..
            }]
        ));
        for (sequence, kind) in [
            CommandKind::PickUp { item_id: hammer_id },
            CommandKind::Wield { item_id: hammer_id },
        ]
        .into_iter()
        .enumerate()
        {
            world
                .advance_tick(vec![ClientCommand {
                    actor_id,
                    sequence: CommandSequence(sequence as u64 + 2),
                    client_tick: world.tick(),
                    kind,
                }])
                .expect("hammer setup should resolve");
        }
        assert_eq!(
            world.actor_bash_strength(actor_id).expect("strength"),
            Some(17),
            "pinned armed smash adds default base Strength 8 to hammer bash 9"
        );
        assert_eq!(
            world
                .actor_smash_action_cost(actor_id)
                .expect("smash action cost"),
            63 * cdda_protocol::ACTION_POINTS_PER_UPSTREAM_MOVE,
            "pinned hammer attack time 79 pays the truncated 80% smash cost"
        );
        assert_eq!(
            world
                .actor_melee_action_cost(actor_id)
                .expect("hammer melee action cost"),
            74 * cdda_protocol::ACTION_POINTS_PER_UPSTREAM_MOVE,
            "attack time 79 halves to 39, adds 39 at melee zero, then subtracts DEX 8 / 2"
        );

        let mut stronger_snapshot = world.snapshot();
        stronger_snapshot
            .actors
            .iter_mut()
            .find(|actor| actor.id == actor_id)
            .expect("actor is canonical")
            .base_strength = 12;
        let stronger =
            WorldState::from_snapshot(&stronger_snapshot).expect("stronger actor restores");
        assert_eq!(
            stronger
                .actor_bash_strength(actor_id)
                .expect("stronger bash resolves"),
            Some(21),
            "canonical base Strength feeds the healthy-arm smash subset"
        );
        let mut overbound_snapshot = stronger_snapshot.clone();
        let overbound_actor = overbound_snapshot
            .actors
            .iter_mut()
            .find(|actor| actor.id == actor_id)
            .expect("actor is canonical");
        overbound_actor.base_strength = MAX_ACTOR_BASE_STAT;
        overbound_actor.base_dexterity = MAX_ACTOR_BASE_STAT;
        let overbound =
            WorldState::from_snapshot(&overbound_snapshot).expect("defensive ceiling restores");
        assert_eq!(
            overbound
                .actor_bash_strength(actor_id)
                .expect("effective Strength cap"),
            Some(29)
        );
        assert_eq!(
            overbound
                .actor_melee_action_cost(actor_id)
                .expect("effective DEX cap"),
            68 * cdda_protocol::ACTION_POINTS_PER_UPSTREAM_MOVE
        );

        let setup_snapshot = world.snapshot();
        assert!(
            setup_snapshot
                .furniture_bash_ids
                .binary_search(&String::from("f_unsupported_actor_bash"))
                .is_ok(),
            "unsupported upstream bash presence remains canonical"
        );
        let mut invalid_strength = setup_snapshot.clone();
        invalid_strength
            .actors
            .iter_mut()
            .find(|actor| actor.id == actor_id)
            .expect("actor is canonical")
            .base_strength = 0;
        assert!(matches!(
            WorldState::from_snapshot(&invalid_strength),
            Err(SimError::InvalidSnapshot)
        ));
        let mut invalid_intelligence = setup_snapshot.clone();
        invalid_intelligence
            .actors
            .iter_mut()
            .find(|actor| actor.id == actor_id)
            .expect("actor is canonical")
            .base_intelligence = 0;
        assert!(matches!(
            WorldState::from_snapshot(&invalid_intelligence),
            Err(SimError::InvalidSnapshot)
        ));
        let setup_world =
            WorldState::from_snapshot(&setup_snapshot).expect("canonical setup restores");
        let mut changed_stats = setup_snapshot.clone();
        let changed_actor = changed_stats
            .actors
            .iter_mut()
            .find(|actor| actor.id == actor_id)
            .expect("actor is canonical");
        changed_actor.base_dexterity = 20;
        changed_actor.base_intelligence = 10;
        changed_actor.base_perception = 11;
        let changed_stats =
            WorldState::from_snapshot(&changed_stats).expect("bounded base stats restore");
        assert_eq!(
            changed_stats
                .actor_melee_action_cost(actor_id)
                .expect("high-DEX hammer cost"),
            68 * cdda_protocol::ACTION_POINTS_PER_UPSTREAM_MOVE
        );
        assert_ne!(
            setup_world.canonical_hash().expect("setup state hashes"),
            changed_stats
                .canonical_hash()
                .expect("changed base stats hash"),
            "all canonical base stats must participate in CanonicalStateV55"
        );
        let mut invalid_profile = setup_snapshot.clone();
        invalid_profile.smash_item_types[0].attack_time_moves = 0;
        assert!(matches!(
            WorldState::from_snapshot(&invalid_profile),
            Err(SimError::InvalidSnapshot)
        ));
        let mut changed_accuracy_profile = setup_snapshot.clone();
        changed_accuracy_profile.smash_item_types[0].melee_to_hit = 0;
        let changed_accuracy_world = WorldState::from_snapshot(&changed_accuracy_profile)
            .expect("bounded weapon accuracy should restore");
        assert_ne!(
            setup_world.canonical_hash().expect("setup state hashes"),
            changed_accuracy_world
                .canonical_hash()
                .expect("changed accuracy state hashes"),
            "strict weapon to-hit must participate in CanonicalStateV55"
        );
        let mut unsupported =
            WorldState::from_snapshot(&setup_snapshot).expect("unsupported setup restores");
        let unsupported_rejection = unsupported
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(4),
                client_tick: unsupported.tick(),
                kind: CommandKind::Smash { dx: 0, dy: -1 },
            }])
            .expect("unsupported furniture smash should resolve");
        assert!(matches!(
            unsupported_rejection.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CommandRejected {
                    reason: CommandRejection::InvalidBashInteraction,
                    ..
                },
                ..
            }]
        ));
        let unsupported_snapshot = unsupported.snapshot();
        let unsupported_chunk = unsupported_snapshot
            .chunks
            .iter()
            .find(|chunk| chunk.coord == unsupported_coord)
            .expect("unsupported target chunk remains");
        let unsupported_index = tile_index(unsupported_local).expect("unsupported target index");
        assert_eq!(
            unsupported_chunk.tiles[unsupported_index].terrain_id, "t_actor_bash_door",
            "unsupported furniture must block the registered terrain beneath it"
        );
        assert_eq!(
            unsupported_chunk.furniture[unsupported_index]
                .as_ref()
                .map(|furniture| furniture.furniture_id.as_str()),
            Some("f_unsupported_actor_bash")
        );

        let mut mixed_damage =
            WorldState::from_snapshot(&world.snapshot()).expect("mixed setup restores");
        mixed_damage
            .actors
            .get_mut(&actor_id)
            .expect("actor remains")
            .inventory
            .get_mut(&hammer_id)
            .expect("hammer remains")
            .melee_damage_milli
            .insert(String::from("cut"), 1_000);
        let mixed_rejection = mixed_damage
            .advance_tick(vec![ClientCommand {
                actor_id,
                sequence: CommandSequence(4),
                client_tick: mixed_damage.tick(),
                kind: CommandKind::Smash { dx: 1, dy: 1 },
            }])
            .expect("unsupported mixed-profile smash should resolve");
        assert!(matches!(
            mixed_rejection.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CommandRejected {
                    reason: CommandRejection::InvalidBashTool,
                    ..
                },
                ..
            }]
        ));
        let mut degraded =
            WorldState::from_snapshot(&world.snapshot()).expect("degraded setup restores");
        degraded
            .actors
            .get_mut(&actor_id)
            .expect("actor remains")
            .inventory
            .get_mut(&hammer_id)
            .expect("hammer remains")
            .damage = 2;
        degraded
            .actors
            .get_mut(&actor_id)
            .expect("actor remains")
            .inventory
            .get_mut(&hammer_id)
            .expect("hammer remains")
            .raw_damage = 1_000;
        assert_eq!(
            degraded
                .actor_bash_strength(actor_id)
                .expect("degraded strength resolves"),
            None,
            "damage adjustment remains fail-closed until item charge mode is canonical"
        );
        let mut mismatched =
            WorldState::from_snapshot(&world.snapshot()).expect("mismatched setup restores");
        *mismatched
            .actors
            .get_mut(&actor_id)
            .expect("actor remains")
            .inventory
            .get_mut(&hammer_id)
            .expect("hammer remains")
            .melee_damage_milli
            .get_mut("bash")
            .expect("hammer has bash damage") = 10_000;
        assert_eq!(
            mismatched
                .actor_bash_strength(actor_id)
                .expect("mismatched strength resolves"),
            None,
            "instance damage must exactly match its canonical smash-item profile"
        );
        let mut ranged =
            WorldState::from_snapshot(&world.snapshot()).expect("ranged setup restores");
        ranged
            .actors
            .get_mut(&actor_id)
            .expect("actor remains")
            .inventory
            .get_mut(&hammer_id)
            .expect("hammer remains")
            .ranged_weapon = Some(RangedWeaponSnapshot {
            ammunition_type: String::from("test_ammo"),
            ammunition_remaining: 1,
            ammunition_capacity: 1,
            range: 1,
            damage: 1,
            dispersion: 1,
            sound_volume: 1,
        });
        assert_eq!(
            ranged
                .actor_bash_strength(actor_id)
                .expect("ranged strength resolves"),
            None,
            "live ranged/ammunition state must not use a static empty-item timing profile"
        );

        let mut replay = WorldState::from_snapshot(&world.snapshot()).expect("setup restores");
        let mut outcomes = Vec::new();
        for sequence in 4..=6 {
            let command = ClientCommand {
                actor_id,
                sequence: CommandSequence(sequence),
                client_tick: world.tick(),
                kind: CommandKind::Smash { dx: 1, dy: 1 },
            };
            let outcome = world
                .advance_tick(vec![command.clone()])
                .expect("actor smash should advance");
            let replay_outcome = replay
                .advance_tick(vec![ClientCommand {
                    client_tick: replay.tick(),
                    ..command
                }])
                .expect("restored smash should advance");
            assert_eq!(outcome, replay_outcome);
            outcomes.push(outcome);
        }
        assert!(matches!(
            outcomes[0].events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::ActorBashed {
                    actor_id: event_actor,
                    target: event_target,
                    target_kind: BashTargetKindV1::Furniture,
                    target_type_id,
                    success: true,
                    damage: 12,
                    ..
                },
                ..
            }] if *event_actor == actor_id
                && *event_target == target
                && target_type_id == "f_actor_bash_table"
        ));
        assert!(matches!(
            outcomes[1].events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::ActorBashed {
                    target_kind: BashTargetKindV1::Terrain,
                    success: false,
                    damage: 8,
                    accumulated_damage: 8,
                    ..
                },
                ..
            }]
        ));
        assert!(matches!(
            outcomes[2].events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::ActorBashed {
                    target_kind: BashTargetKindV1::Terrain,
                    success: true,
                    damage: 8,
                    accumulated_damage: 0,
                    ..
                },
                ..
            }]
        ));
        let snapshot = world.snapshot();
        let index = tile_index(local).expect("target index");
        assert_eq!(snapshot.chunks[0].tiles[index].terrain_id, "t_floor");
        assert_eq!(snapshot.chunks[0].furniture[index], None);
        assert_eq!(snapshot.chunks[0].map_damage[index], 0);
        assert_eq!(
            world.canonical_hash().expect("live hash"),
            replay.canonical_hash().expect("replay hash")
        );
    }

    #[test]
    fn item_group_planner_preserves_order_counts_charges_and_named_distribution() {
        let catalog = [ItemGroupDefinitionV1 {
            group_id: String::from("weighted_child"),
            graph: ItemGroupGraphV1 {
                root_node: 0,
                nodes: vec![ItemGroupNodeV1 {
                    node_id: 0,
                    kind: ItemGroupKindV1::Distribution,
                    entries: vec![
                        ItemGroupEntryV1 {
                            probability: 1,
                            count_min: 1,
                            count_max: 1,
                            raw_damage: None,
                            variant_id: None,
                            event: None,
                            target: test_item_group_leaf("beta", None, false),
                            modifier_charges: None,
                            contents: Vec::new(),
                            seal_contents: false,
                            modifier_default_container_sealed: None,
                            direct_wrapper: None,
                            modifier_container: None,
                        },
                        ItemGroupEntryV1 {
                            probability: 2,
                            count_min: 1,
                            count_max: 1,
                            raw_damage: None,
                            variant_id: None,
                            event: None,
                            target: test_item_group_leaf("gamma", None, false),
                            modifier_charges: None,
                            contents: Vec::new(),
                            seal_contents: false,
                            modifier_default_container_sealed: None,
                            direct_wrapper: None,
                            modifier_container: None,
                        },
                    ],
                }],
                wrapper: None,
            },
        }];
        let source = ItemGroupSourceV1::Inline(ItemGroupGraphV1 {
            root_node: 0,
            nodes: vec![ItemGroupNodeV1 {
                node_id: 0,
                kind: ItemGroupKindV1::Collection,
                entries: vec![
                    ItemGroupEntryV1 {
                        probability: 100,
                        count_min: 2,
                        count_max: 2,
                        raw_damage: Some(cdda_protocol::InclusiveU16RangeV1 {
                            minimum: 0,
                            maximum: 0,
                        }),
                        variant_id: None,
                        event: None,
                        target: test_item_group_leaf("alpha", None, false),
                        modifier_charges: None,
                        contents: Vec::new(),
                        seal_contents: false,
                        modifier_default_container_sealed: None,
                        direct_wrapper: None,
                        modifier_container: None,
                    },
                    ItemGroupEntryV1 {
                        probability: 100,
                        count_min: 1,
                        count_max: 1,
                        raw_damage: None,
                        variant_id: None,
                        event: None,
                        target: ItemGroupTargetV1::Group(String::from("weighted_child")),
                        modifier_charges: None,
                        contents: Vec::new(),
                        seal_contents: false,
                        modifier_default_container_sealed: None,
                        direct_wrapper: None,
                        modifier_container: None,
                    },
                    ItemGroupEntryV1 {
                        probability: 100,
                        count_min: 2,
                        count_max: 2,
                        raw_damage: Some(cdda_protocol::InclusiveU16RangeV1 {
                            minimum: 0,
                            maximum: 0,
                        }),
                        variant_id: None,
                        event: None,
                        target: test_item_group_leaf(
                            "charged",
                            Some(cdda_protocol::InclusiveI32RangeV1 {
                                minimum: 0,
                                maximum: 2,
                            }),
                            true,
                        ),
                        modifier_charges: None,
                        contents: Vec::new(),
                        seal_contents: false,
                        modifier_default_container_sealed: None,
                        direct_wrapper: None,
                        modifier_container: None,
                    },
                ],
            }],
            wrapper: None,
        });
        let catalog_map = catalog
            .iter()
            .cloned()
            .map(|definition| (definition.group_id.clone(), definition))
            .collect::<BTreeMap<_, _>>();
        let mut first_rng = ChaCha8Rng::from_seed([7; 32]);
        let first = plan_item_group_source(&source, &catalog_map, &mut first_rng)
            .expect("valid group should plan");
        let mut second_rng = ChaCha8Rng::from_seed([7; 32]);
        let second = plan_item_group_source(&source, &catalog_map, &mut second_rng)
            .expect("same group should plan again");
        assert_eq!(first, second, "the same named stream must replay exactly");
        assert_eq!(first.len(), 5);
        assert_eq!(
            first
                .iter()
                .map(|prototype| prototype.prototype.type_id.as_str())
                .collect::<Vec<_>>(),
            vec!["alpha", "alpha", "beta", "charged", "charged"]
        );
        assert!(
            first[3..]
                .iter()
                .all(|prototype| (1..=2).contains(&prototype.prototype.charges))
        );
    }

    #[test]
    fn item_group_catalog_registration_is_atomic_and_snapshot_stable() {
        let catalog = vec![ItemGroupDefinitionV1 {
            group_id: String::from("stable_group"),
            graph: ItemGroupGraphV1 {
                root_node: 0,
                nodes: vec![ItemGroupNodeV1 {
                    node_id: 0,
                    kind: ItemGroupKindV1::Collection,
                    entries: vec![ItemGroupEntryV1 {
                        probability: 100,
                        count_min: 1,
                        count_max: 1,
                        raw_damage: None,
                        variant_id: None,
                        event: None,
                        target: test_item_group_leaf("rock", None, false),
                        modifier_charges: None,
                        contents: Vec::new(),
                        seal_contents: false,
                        modifier_default_container_sealed: None,
                        direct_wrapper: None,
                        modifier_container: None,
                    }],
                }],
                wrapper: None,
            },
        }];
        let mut world = WorldState::new(83, [83; 32]);
        world
            .register_item_group_catalog(catalog.clone())
            .expect("valid catalog should register");
        world
            .register_terrain_bash_type(TerrainBashTypeV1 {
                terrain_id: String::from("t_group_test"),
                str_min: 1,
                str_max: 1,
                str_min_blocked: -1,
                str_max_blocked: -1,
                str_min_supported: -1,
                str_max_supported: -1,
                bash_multiplier_millionths: 1_000_000,
                result: test_terrain("t_floor"),
                drop_source: Some(ItemGroupSourceV1::Group(String::from("stable_group"))),
                hit_field: None,
                destroyed_field: None,
                sound: String::from("smash"),
                failure_sound: String::from("whump"),
                sound_volume: -1,
                failure_sound_volume: -1,
            })
            .expect("catalog consumer should register");
        assert_eq!(world.snapshot().item_groups, catalog);
        let restored =
            WorldState::from_snapshot(&world.snapshot()).expect("catalog should restore");
        assert_eq!(restored.snapshot(), world.snapshot());

        let mut nonminimal = world.snapshot();
        nonminimal.item_groups.push(ItemGroupDefinitionV1 {
            group_id: String::from("unused_group"),
            graph: ItemGroupGraphV1 {
                root_node: 0,
                nodes: vec![ItemGroupNodeV1 {
                    node_id: 0,
                    kind: ItemGroupKindV1::Collection,
                    entries: Vec::new(),
                }],
                wrapper: None,
            },
        });
        assert!(matches!(
            WorldState::from_snapshot(&nonminimal),
            Err(SimError::InvalidSnapshot)
        ));

        let mut conflicting = world.snapshot().item_groups;
        conflicting[0].graph.nodes[0].entries[0].count_max = 2;
        let before = world.snapshot();
        assert!(matches!(
            world.register_item_group_catalog(conflicting),
            Err(SimError::InvalidItem)
        ));
        assert_eq!(
            world.snapshot(),
            before,
            "failed replacement must be atomic"
        );

        world.tick = SimTick(1);
        assert!(matches!(
            world.register_item_group_catalog(catalog),
            Err(SimError::InvalidItem)
        ));
    }

    #[test]
    fn item_group_guaranteed_collection_and_implicit_damage_preserve_rng_order() {
        let source = ItemGroupSourceV1::Inline(ItemGroupGraphV1 {
            root_node: 0,
            nodes: vec![ItemGroupNodeV1 {
                node_id: 0,
                kind: ItemGroupKindV1::Collection,
                entries: vec![ItemGroupEntryV1 {
                    probability: 100,
                    count_min: 2,
                    count_max: 2,
                    raw_damage: Some(cdda_protocol::InclusiveU16RangeV1 {
                        minimum: 0,
                        maximum: 0,
                    }),
                    variant_id: None,
                    event: None,
                    target: test_item_group_leaf(
                        "fixed_charges",
                        Some(cdda_protocol::InclusiveI32RangeV1 {
                            minimum: 5,
                            maximum: 5,
                        }),
                        false,
                    ),
                    modifier_charges: None,
                    contents: Vec::new(),
                    seal_contents: false,
                    modifier_default_container_sealed: None,
                    direct_wrapper: None,
                    modifier_container: None,
                }],
            }],
            wrapper: None,
        });
        let seed = [91; 32];
        let mut actual_rng = ChaCha8Rng::from_seed(seed);
        let planned = plan_item_group_source(&source, &BTreeMap::new(), &mut actual_rng)
            .expect("fixed group should plan");
        assert_eq!(planned.len(), 2);
        assert!(
            planned
                .iter()
                .all(|prototype| prototype.prototype.charges == 5)
        );

        let mut expected_rng = ChaCha8Rng::from_seed(seed);
        let _guaranteed_collection_roll = expected_rng.next_u64();
        let _first_item_seed_roll = expected_rng.next_u64();
        let _first_variant_roll = expected_rng.next_u64();
        let _first_fit_roll = expected_rng.next_u64();
        let _first_fixed_zero_damage_roll = expected_rng.next_u64();
        let _second_item_seed_roll = expected_rng.next_u64();
        let _second_variant_roll = expected_rng.next_u64();
        let _second_fit_roll = expected_rng.next_u64();
        let _second_fixed_zero_damage_roll = expected_rng.next_u64();
        assert_eq!(
            actual_rng.next_u64(),
            expected_rng.next_u64(),
            "fixed count and charges skip their own draws, but constructor, fit, and Item_modifier phases remain per item"
        );
    }

    #[test]
    fn group_bash_persists_damage_and_atomically_transforms_drops_fields_and_sound() {
        let mut world = WorldState::new(41, [19; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        for field_type_id in ["fd_dust", "fd_splinters"] {
            let mut field_type = test_field_type(field_type_id, 0, false);
            field_type.intensity_levels = vec![field_type.intensity_levels[0].clone(); 3];
            world
                .register_field_type(field_type)
                .expect("bash field should register");
        }
        let mut closed_door = test_terrain("t_door_c");
        closed_door.move_cost = 0;
        closed_door.transparent = false;
        let mut damaged_door = test_terrain("t_door_b");
        damaged_door.move_cost = 0;
        let door_bash = TerrainBashTypeV1 {
            terrain_id: String::from("t_door_c"),
            str_min: 8,
            str_max: 12,
            str_min_blocked: 15,
            str_max_blocked: 20,
            str_min_supported: -1,
            str_max_supported: -1,
            bash_multiplier_millionths: 950_000,
            result: damaged_door.clone(),
            drop_source: Some(ItemGroupSourceV1::Inline(ItemGroupGraphV1 {
                root_node: 0,
                nodes: vec![cdda_protocol::ItemGroupNodeV1 {
                    node_id: 0,
                    kind: ItemGroupKindV1::Collection,
                    entries: vec![cdda_protocol::ItemGroupEntryV1 {
                        probability: 100,
                        count_min: 1,
                        count_max: 1,
                        raw_damage: None,
                        variant_id: None,
                        event: None,
                        target: ItemGroupTargetV1::Item(Box::new(
                            cdda_protocol::ItemGroupItemPrototypeV1 {
                                prototype: CraftItemPrototypeV1 {
                                    type_id: String::from("splinter"),
                                    charges: 1,
                                    melee_damage_milli: BTreeMap::new(),
                                    calories: 0,
                                    quench: 0,
                                    comestible_type: String::new(),
                                    tracks_temperature: false,
                                    ammunition_type: String::new(),
                                    ranged_weapon: None,
                                    magazine_capacity: 0,
                                    integral_magazines: Vec::new(),
                                    magazine_wells: Vec::new(),
                                    ammunition_containers: Vec::new(),
                                    residual_energy_millijoules: 0,
                                    powered_tool: None,
                                    containment: Default::default(),
                                },
                                maximum_raw_damage: cdda_protocol::MAX_ITEM_RAW_DAMAGE,
                                variants: Vec::new(),
                                description_expansion: None,
                                snippets: Vec::new(),
                                initial_variables: BTreeMap::new(),
                                default_container: None,
                                modifier_side_effects_supported: true,
                                charges: None,
                                minimum_one_charge: false,
                                tool_charge_storage: None,
                                charges_supported: true,
                                modifier_container_capacity_applies: true,
                                contents_insertion_supported: true,
                            },
                        )),
                        modifier_charges: None,
                        contents: Vec::new(),
                        seal_contents: false,
                        modifier_default_container_sealed: None,
                        direct_wrapper: None,
                        modifier_container: None,
                    }],
                }],
                wrapper: None,
            })),
            hit_field: Some(cdda_protocol::BashFieldEffectV1 {
                field_type_id: String::from("fd_dust"),
                intensity: 2,
            }),
            destroyed_field: Some(cdda_protocol::BashFieldEffectV1 {
                field_type_id: String::from("fd_splinters"),
                intensity: 1,
            }),
            sound: String::from("smash!"),
            failure_sound: String::from("whump!"),
            sound_volume: 70,
            failure_sound_volume: -1,
        };
        let mut invalid_sound = door_bash.clone();
        invalid_sound.sound_volume = i32::from(u16::MAX) + 1;
        assert!(matches!(
            world.register_terrain_bash_type(invalid_sound),
            Err(SimError::InvalidTerrain)
        ));
        world
            .register_terrain_bash_type(door_bash)
            .expect("door bash should register");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        let mut corridor_wall = test_terrain("t_wall");
        corridor_wall.move_cost = 0;
        corridor_wall.transparent = false;
        for x in 0..SUBMAP_SIZE as u8 {
            for y in [0, 2] {
                chunk
                    .set_terrain(LocalTileCoord { x, y }, corridor_wall.clone())
                    .expect("corridor wall should install");
            }
        }
        chunk
            .set_terrain(LocalTileCoord { x: 4, y: 1 }, closed_door)
            .expect("door should install");
        world.insert_chunk(chunk);
        let actor = world
            .spawn_actor(WorldPosition { x: 5, y: 1, z: 0 }, true)
            .expect("target should spawn");
        let spawn_bashing_zombie = |world: &mut WorldState, x| {
            world
                .spawn_creature(CreatureSpawn {
                    type_id: String::from("mon_zombie"),
                    position: WorldPosition { x, y: 1, z: 0 },
                    hp: 80,
                    speed: 70,
                    attack_cost_moves: 100,
                    aggression: 100,
                    melee_skill: 0,
                    dodge: 0,
                    size: Default::default(),
                    melee_dice: 2,
                    melee_dice_sides: 3,
                    can_see: true,
                    vision_day: 40,
                    vision_night: 3,
                    stumbles: true,
                    bashes: true,
                    group_bash: true,
                    hears: false,
                    good_hearing: false,
                    clumsy_attacks: false,
                    immobile: false,
                    pacifist: false,
                    can_open_doors: false,
                    path_settings: Default::default(),
                    blood_field_type_id: String::new(),
                    corpse: None,
                })
                .expect("zombie should spawn")
        };
        let basher = spawn_bashing_zombie(&mut world, 3);
        world.creatures.get_mut(&basher).expect("basher").goal =
            Some(world.actor_snapshot(actor).expect("target").position);
        let solo_event = loop {
            let outcome = world.advance_tick(Vec::new()).expect("solo bash tick");
            if let Some(event) = outcome
                .events
                .into_iter()
                .find(|event| matches!(event.kind, WorldEventKind::CreatureBashed { .. }))
            {
                break event;
            }
        };
        assert!(matches!(
            solo_event.kind,
            WorldEventKind::CreatureBashed {
                creature_id,
                damage: 0,
                success: false,
                volume: 12,
                ..
            } if creature_id == basher
        ));
        assert_eq!(
            world.snapshot().chunks[0].map_damage
                [tile_index(LocalTileCoord { x: 4, y: 1 }).expect("index")],
            0,
            "one default zombie cannot damage a closed wooden door"
        );
        for x in [2, 1] {
            let helper = spawn_bashing_zombie(&mut world, x);
            world.creatures.get_mut(&helper).expect("helper").goal =
                Some(world.actor_snapshot(actor).expect("target").position);
        }
        let sound_listener = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_sound_listener"),
                position: WorldPosition { x: 10, y: 1, z: 0 },
                hp: 20,
                speed: 1,
                attack_cost_moves: 100,
                aggression: 0,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 0,
                melee_dice_sides: 1,
                can_see: false,
                vision_day: 0,
                vision_night: 0,
                stumbles: false,
                bashes: false,
                group_bash: false,
                hears: true,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("sound listener should spawn");
        assert_eq!(
            world.creature_snapshot(basher).expect("basher").position,
            WorldPosition { x: 3, y: 1, z: 0 }
        );
        assert_eq!(
            world
                .creature_group_bash_strength(basher, WorldPosition { x: 4, y: 1, z: 0 })
                .expect("group strength"),
            11
        );
        let mut observed_bashes = Vec::new();
        let positive_event = (0..300)
            .find_map(|_| {
                let basher_state = world.creatures.get(&basher).expect("basher remains");
                if basher_state.action_points + i64::from(basher_state.speed)
                    >= i64::from(CREATURE_ACTION_THRESHOLD)
                {
                    assert_eq!(basher_state.position, WorldPosition { x: 3, y: 1, z: 0 });
                    assert_eq!(
                        world
                            .creature_group_bash_strength(
                                basher,
                                WorldPosition { x: 4, y: 1, z: 0 },
                            )
                            .expect("turn group strength"),
                        11
                    );
                }
                let outcome = world.advance_tick(Vec::new()).expect("group bash tick");
                for event in outcome.events {
                    if let WorldEventKind::CreatureBashed {
                        creature_id,
                        target,
                        damage,
                        ..
                    } = &event.kind
                    {
                        observed_bashes.push((*creature_id, *target, *damage));
                        if *damage > 0 {
                            return Some(event);
                        }
                    }
                }
                None
            })
            .unwrap_or_else(|| panic!("group never damaged door; bashes={observed_bashes:?}"));
        let positive_damage = match positive_event.kind {
            WorldEventKind::CreatureBashed {
                damage,
                success: false,
                accumulated_damage,
                ..
            } => {
                assert_eq!(accumulated_damage, damage);
                damage
            }
            ref kind => panic!("unexpected positive bash event {kind:?}"),
        };
        assert!(positive_damage > 0);
        let partial_hash = world.canonical_hash().expect("partial hash");
        let mut replay = WorldState::from_snapshot(&world.snapshot()).expect("partial restore");
        assert_eq!(
            replay.canonical_hash().expect("restored hash"),
            partial_hash
        );
        for candidate in [&mut world, &mut replay] {
            candidate.allocator.next = candidate
                .allocator
                .reserved_end
                .checked_add(1)
                .expect("reservation end should advance");
        }
        let allocation_blocked = (0..500)
            .find_map(|_| {
                let outcome = world
                    .advance_tick(Vec::new())
                    .expect("allocation-blocked bash tick");
                let replay_outcome = replay
                    .advance_tick(Vec::new())
                    .expect("allocation-blocked replay tick");
                assert_eq!(outcome, replay_outcome);
                outcome
                    .events
                    .iter()
                    .any(|event| {
                        matches!(
                            event.kind,
                            WorldEventKind::CreatureBashed {
                                success: false,
                                accumulated_damage: 11,
                                ..
                            }
                        )
                    })
                    .then_some(outcome)
            })
            .expect("exhausted IDs should hold structural damage below success");
        assert!(allocation_blocked.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CreatureBashed {
                success: false,
                accumulated_damage: 11,
                ..
            }
        )));
        let blocked_snapshot = world.snapshot();
        let door_index = tile_index(LocalTileCoord { x: 4, y: 1 }).expect("door index");
        assert_eq!(
            blocked_snapshot.chunks[0].tiles[door_index].terrain_id,
            "t_door_c"
        );
        assert_eq!(blocked_snapshot.chunks[0].map_damage[door_index], 11);
        assert!(blocked_snapshot.ground_items.is_empty());
        for candidate in [&mut world, &mut replay] {
            candidate
                .install_reserved_block(
                    ReservedIdBlock::new(4_097, 8_192).expect("replacement block"),
                )
                .expect("replacement reservation should install");
        }
        let completed = (0..500)
            .find_map(|_| {
                let outcome = world
                    .advance_tick(Vec::new())
                    .expect("bash completion tick");
                let replay_outcome = replay.advance_tick(Vec::new()).expect("replay bash tick");
                assert_eq!(outcome, replay_outcome);
                outcome
                    .events
                    .iter()
                    .any(|event| {
                        matches!(
                            event.kind,
                            WorldEventKind::CreatureBashed { success: true, .. }
                        )
                    })
                    .then_some(outcome)
            })
            .expect("group bash should eventually destroy the door");
        assert!(completed.events.iter().any(|event| matches!(
            event.kind,
            WorldEventKind::CreatureBashed {
                success: true,
                ref sound,
                volume: 70,
                ..
            } if sound == "smash!"
        )));
        assert!(
            world
                .creature_snapshot(sound_listener)
                .expect("sound listener should remain")
                .sound_goal
                .is_some(),
            "canonical structural sound should feed private monster hearing"
        );
        let snapshot = world.snapshot();
        assert_eq!(snapshot.chunks[0].tiles[door_index], damaged_door);
        assert_eq!(snapshot.chunks[0].map_damage[door_index], 0);
        assert!(snapshot.ground_items.iter().any(|ground| {
            ground.item.type_id == "splinter" && ground.item.id.world_namespace() == 41
        }));
        let fields = &snapshot.chunks[0].fields[door_index];
        assert!(fields.iter().any(|field| field.field_type_id == "fd_dust"));
        assert!(
            fields
                .iter()
                .any(|field| field.field_type_id == "fd_splinters")
        );
        assert_eq!(
            replay.canonical_hash().expect("replay final hash"),
            world.canonical_hash().expect("live final hash")
        );
    }

    #[test]
    fn furniture_bash_precedes_terrain_and_door_frame_repairs_to_floor() {
        let mut world = WorldState::new(59, [59; 32]);
        world
            .install_reserved_block(ReservedIdBlock::new(1, 4_096).expect("valid block"))
            .expect("block should install");
        world
            .register_terrain_bash_type(TerrainBashTypeV1 {
                terrain_id: String::from("t_door_frame"),
                str_min: 6,
                str_max: 25,
                str_min_blocked: -1,
                str_max_blocked: -1,
                str_min_supported: -1,
                str_max_supported: -1,
                bash_multiplier_millionths: 1_000_000,
                result: test_terrain("t_floor"),
                drop_source: None,
                hit_field: None,
                destroyed_field: None,
                sound: String::from("crunch!"),
                failure_sound: String::from("whump!"),
                sound_volume: -1,
                failure_sound_volume: -1,
            })
            .expect("door-frame bash should register");
        world
            .register_furniture_bash_type(FurnitureBashTypeV1 {
                furniture_id: String::from("f_dresser"),
                str_min: 12,
                str_max: 40,
                str_min_blocked: -1,
                str_max_blocked: -1,
                str_min_supported: -1,
                str_max_supported: -1,
                bash_multiplier_millionths: 1_000_000,
                result: None,
                drop_source: None,
                hit_field: None,
                destroyed_field: None,
                sound: String::from("smash!"),
                failure_sound: String::from("whump."),
                sound_volume: -1,
                failure_sound_volume: -1,
            })
            .expect("dresser bash should register");
        let mut chunk = Chunk::floor(ChunkCoord { x: 0, y: 0, z: 0 });
        chunk
            .set_terrain(
                LocalTileCoord { x: 4, y: 1 },
                TerrainTileSnapshot {
                    move_cost: 2,
                    ..test_terrain("t_door_frame")
                },
            )
            .expect("door frame should install");
        chunk
            .set_furniture(
                LocalTileCoord { x: 4, y: 1 },
                Some(test_furniture("f_dresser", -1, true)),
            )
            .expect("dresser should install");
        world.insert_chunk(chunk);
        let creature_id = world
            .spawn_creature(CreatureSpawn {
                type_id: String::from("mon_strong_basher"),
                position: WorldPosition { x: 3, y: 1, z: 0 },
                hp: 80,
                speed: u16::try_from(CREATURE_ACTION_THRESHOLD).expect("threshold fits"),
                attack_cost_moves: 100,
                aggression: 100,
                melee_skill: 0,
                dodge: 0,
                size: Default::default(),
                melee_dice: 10,
                melee_dice_sides: 10,
                can_see: false,
                vision_day: 0,
                vision_night: 0,
                stumbles: false,
                bashes: true,
                group_bash: false,
                hears: false,
                good_hearing: false,
                clumsy_attacks: false,
                immobile: false,
                pacifist: false,
                can_open_doors: false,
                path_settings: Default::default(),
                blood_field_type_id: String::new(),
                corpse: None,
            })
            .expect("basher should spawn");
        world
            .creatures
            .get_mut(&creature_id)
            .expect("basher should remain")
            .goal = Some(WorldPosition { x: 5, y: 1, z: 0 });
        let mut replay = WorldState::from_snapshot(&world.snapshot())
            .expect("pre-bash furniture state should restore");

        let furniture_outcome = world
            .advance_tick(Vec::new())
            .expect("furniture bash tick should advance");
        let replay_furniture_outcome = replay
            .advance_tick(Vec::new())
            .expect("restored furniture bash tick should advance");
        assert_eq!(furniture_outcome, replay_furniture_outcome);
        assert!(matches!(
            furniture_outcome.events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CreatureBashed {
                    creature_id: event_creature,
                    target_kind: BashTargetKindV1::Furniture,
                    target_type_id,
                    success: true,
                    ..
                },
                ..
            }] if *event_creature == creature_id && target_type_id == "f_dresser"
        ));
        let after_furniture = world.snapshot();
        let index = tile_index(LocalTileCoord { x: 4, y: 1 }).expect("tile index");
        assert!(after_furniture.chunks[0].furniture[index].is_none());
        assert_eq!(
            after_furniture.chunks[0].tiles[index].terrain_id,
            "t_door_frame"
        );
        assert_eq!(after_furniture.chunks[0].map_damage[index], 0);

        let mut terrain_events = Vec::new();
        let mut replay_terrain_events = Vec::new();
        world
            .perform_creature_bash(
                creature_id,
                WorldPosition { x: 4, y: 1, z: 0 },
                1,
                &mut terrain_events,
            )
            .expect("door frame should bash");
        replay
            .perform_creature_bash(
                creature_id,
                WorldPosition { x: 4, y: 1, z: 0 },
                1,
                &mut replay_terrain_events,
            )
            .expect("restored door frame should bash");
        assert_eq!(terrain_events, replay_terrain_events);
        assert!(matches!(
            terrain_events.as_slice(),
            [WorldEvent {
                kind: WorldEventKind::CreatureBashed {
                    target_kind: BashTargetKindV1::Terrain,
                    target_type_id,
                    success: true,
                    ..
                },
                ..
            }] if target_type_id == "t_door_frame"
        ));
        let final_snapshot = world.snapshot();
        assert_eq!(final_snapshot.chunks[0].tiles[index].terrain_id, "t_floor");
        assert!(final_snapshot.chunks[0].furniture[index].is_none());
        assert_eq!(final_snapshot.chunks[0].map_damage[index], 0);
        WorldState::from_snapshot(&final_snapshot)
            .expect("furniture and final terrain results should restore");
        assert_eq!(
            world.canonical_hash().expect("live state should hash"),
            replay.canonical_hash().expect("restored state should hash")
        );
    }

